{
  "name": "@amykit/workflow-ticket-to-qa",
  "version": "0.6.0",
  "description": "The ticket-to-QA workflow: its states, its typed port contracts, and a pure plan().",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "examples/workflow-ticket-to-qa"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "workflow.mmd"
  ],
  "dependencies": {
    "@amykit/agent-kit": "^0.6.0",
    "@amykit/core": "^0.6.0",
    "yaml": "^2.8.1",
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@amykit/plugin-file-queue": "^0.6.0",
    "@amykit/plugin-file-store": "^0.6.0",
    "@amykit/plugin-serial-engine": "^0.6.0",
    "@amykit/test-fixtures": "^0.1.0",
    "fast-check": "^4.10.2",
    "@amykit/workflow-testkit": "^0.6.0"
  }
}

import {
  ActionContext,
  AgentRun,
  Ask,
  baseBranchFor,
  Conversation,
  FoundWork,
  Moved,
  renderBrief,
  sayToOperator,
  ProgressPolicy,
  PullRequestView,
  WorkflowActionScope,
  WorkflowPieceContext,
  parseBudget,
} from "@amykit/core";
import type { Git } from "@amykit/core";
import { implementStep, judgeStep } from "@amykit/agent-kit";
import {
  ReviewerHints,
  branchOf,
  discussPrompt,
  implementPrompt,
  readTriage,
  readVerdicts,
  threadPrompt,
  triagePrompt,
  unreadTriage,
  questionText,
} from "./agent-steps.js";
import { Effect, WRITE_EFFECTS, WriteEffect } from "./effects.js";
import { Observation, Policy, Said } from "./observation.js";
import { decided, decisionLines } from "./discussion.js";
import { EffectOutcomes, applyOutcomes, applyTransition } from "./outcomes.js";
import type { configSchema, needs } from "./plugin.js";
import { loadRoster } from "./roster.js";
import { TicketRecord } from "./record.js";
import { Ticket, pullRequestTitle } from "./ticket.js";

/**
 * How this workflow's work is found and looked at, what each action does, and
 * how the result folds back in — each a function of what the declaration
 * hands it: the mounted ports, the settings, the policy and the checkouts.
 *
 * It lived inside the engine, and that is what made the engine drive exactly
 * one workflow. Everything here names a ticket, a pull request or a reviewer,
 * so it belongs on this side of the boundary; what stayed behind is a queue,
 * a budget, a retry count and a stop switch, which name nothing.
 */
type Scope = WorkflowPieceContext<typeof configSchema, Policy, typeof needs>;
type ActionScope = WorkflowActionScope<typeof configSchema, Policy, typeof needs>;
type Work = ActionContext<TicketRecord, Observation>;

/** The part of `Git` this workflow drives, for a test that hands a fake rather than a git. */
export type TicketGit = Pick<Git, "pathFor" | "acquire" | "prepareBranch" | "commitAndPush" | "headSha">;

/** Exhaustive over this workflow's actions, checked at compile time. */
type TicketActions = {
  [K in Effect["type"]]: (scope: ActionScope, work: Work, effect: Extract<Effect, { type: K }>) => Promise<void>;
};

/** Evidence-progress policy, when this install opted in under `budget`. */
export function progress(scope: Scope): ProgressPolicy | undefined {
  const parsed = parseBudget(scope.config.budget);
  if (!parsed.ok) throw new Error(parsed.problems.join("; "));
  return parsed.limits.progress;
}

/**
 * One work item per repository. The ticket's own repository keeps the
 * ticket's own id, so a ticket labelled into more repositories while its
 * work is under way keeps that work item and gains one per new repository,
 * instead of starting the same work again under a new name. A ticket in
 * several is refused here, before any of it starts, when the host could
 * never say they had all merged.
 */
export async function discover(scope: Scope): Promise<FoundWork[]> {
  return (await scope.ports.tracker.inProgress()).flatMap((ticket) => {
    const priority = ticket.priority === undefined ? {} : { priority: ticket.priority };
    if ((ticket.repos?.length ?? 0) > 1) requireMergeLookup(scope, ticket);
    return (ticket.repos ?? [ticket.repo]).map((repo) => ({
      workId: repo === ticket.repo ? ticket.id : workIdFor(ticket.id, repo),
      ...priority,
    }));
  });
}

export async function observe(scope: Scope, current: TicketRecord): Promise<Observation> {
  const ticket = await requireTicketWithBrief(scope, current.id);
  // A ticket whose tracker derived no branch is refused here, on its
  // first look, before any branch is prepared for it.
  const pullRequest = await pullRequestFor(scope, ticket, current.state);

  // Only fetched where it is used, so a poll that is only waiting for a
  // review does not hammer the code host counting everybody's workload.
  const reviewLoad =
    current.state === "REVIEWER_ASSIGNED"
      ? await scope.ports["code-host"].reviewLoad(scope.config.repos)
      : {};

  return {
    ticket,
    pullRequest,
    reviewLoad,
    // Read when a look needs it, not at mount, so confirming the roster
    // takes effect without a restart. With the recovery root named: the
    // machine's state directory, since a phase's profile-own directory is
    // not its parent, so the fallback must not guess from dirname.
    roster: loadRoster(scope.ctx.paths.profile ?? scope.ctx.paths.state, scope.ctx.paths.state),
    ...(await answersFor(scope, current, ticket)),
    ...(await whereItStands(scope, ticket, current.state)),
    now: scope.ctx.now(),
  };
}

/**
 * Only this workflow's own half of the fold.
 *
 * The engine has already put the record through `applyPlan` — the state,
 * the attempt count and the history — and folding it again here counted
 * every retry twice and wrote a transition from each state to itself.
 * `applyTicketPlan` is still what a caller driving the machine *without*
 * an engine wants, which is why both exist.
 */
export function remember(
  scope: Scope,
  current: TicketRecord,
  outcomes: Record<string, unknown>,
  observation: Observation,
  moved: Moved | null,
  _decision: unknown,
  now: Date,
): TicketRecord {
  const folded = outcomes as EffectOutcomes;

  // The owner's answer to an escalation arrives as an observation rather
  // than as the result of an action — the move it unblocks carries no
  // action at all — so it is folded here rather than by a handler.
  const settled =
    current.escalation && !current.escalation.resolvedAt && observation.escalationAnswered
      ? {
          ...folded,
          escalationResolvedAt: now.toISOString(),
          escalationDecision: decisionLines(current, observation.conversation, scope.policy, current.escalation.askedAt),
        }
      : folded;

  return toTheChecks(applyTransition(applyOutcomes(current, settled), moved), observation, moved);
}

/**
 * The actions this install may run. With the writes handed to the operator,
 * not a single action that writes is declared, so the mount can hold the
 * empty claim to its word: nothing here could reach a write even by mistake.
 */
export function actionsFor(policy: Policy): Partial<TicketActions> {
  return Object.fromEntries(Object.entries(ACTIONS).filter(([name]) => policy.writes === "operator"
    ? !(WRITE_EFFECTS as readonly string[]).includes(name)
    : name !== "hand-over"));
}

/** The outcomes bag, typed at the one boundary that knows what is in it. */
const outcomesOf = (work: Work): EffectOutcomes => work.outcomes as EffectOutcomes;

const ACTIONS: TicketActions = {
  "triage": async (scope, work, effect) => {
    const ticket = work.observation.ticket;
    const at = scope.ctx.now().toISOString();
    const { value, run } = await judgeStep(scope.ports.agent, {
      prompt: triagePrompt(ticket, effect.conversation),
      cwd: await scope.checkouts.git.acquire(ticket.repo, work.record.id),
      context: { workId: work.record.id, step: "triage" },
      read: (answer) => readTriage(answer, at),
      fallback: unreadTriage(at),
    });
    refuseAnIncompleteRun("triage", run);
    outcomesOf(work).triage = value;
    if (effect.conversation?.length) outcomesOf(work).clarification = effect.conversation;
  },

  "ask-question": async (scope, work, effect) => {
    const { conversation, tracker, brief } = scope.ports;
    if (conversation) {
      const thread = await conversation.open(work.record.id, work.observation.ticket.title);
      if (conversation.asks) {
        for (const question of effect.questions) {
          if (typeof question === "string") {
            await conversation.post(thread, { text: question });
          } else {
            const ask = askFor(question);
            await conversation.post(thread, { text: ask.prompt, ask });
          }
        }
      } else {
        await conversation.post(thread, { text: numberedQuestions(effect.questions) });
      }
    } else {
      await tracker.comment(
        work.observation.ticket.id,
        numberedQuestions(effect.questions),
      );
    }
    await scope.announce(`${work.record.id} needs an answer before I can start.`);

    // The same question, appended to the brief it is about, with this
    // ticket's id and the time — the one channel a later sibling reads.
    // Nothing appends an answer: deciding the question is the owning
    // workflow's revision, never this workflow's write.
    const briefId = work.observation.ticket.briefId;
    if (briefId && brief) {
      for (const question of effect.questions) {
        await brief.appendQuestion({
          id: briefId,
          question: { workId: work.record.id, question: questionText(question), at: scope.ctx.now().toISOString() },
          at: scope.ctx.now().toISOString(),
        });
      }
    }
  },

  "implement": async (scope, work, effect) => {
    const { git } = scope.checkouts;
    const ticket = work.observation.ticket;
    const branch = branchOf(ticket);
    await git.prepareBranch(ticket.repo, branch, work.record.id);
    const { value, run } = await implementStep(scope.ports.agent, {
      prompt: implementPrompt(
        ticket,
        effect.retryContext,
        effect.continuationContext,
        effect.conversation,
        effect.discussion,
      ),
      cwd: await git.acquire(ticket.repo, work.record.id),
      context: { workId: work.record.id, step: "implement" },
      commit: () => git.commitAndPush(ticket.repo, branch, `${ticket.id}: ${ticket.title}`, work.record.id),
      now: scope.ctx.now,
    });
    if (run.outcome === "rate-limited") {
      outcomesOf(work).waited = { notATry: true, retryAfterMs: run.retryAfterMs ?? scope.policy.pollBackoffMs };
      outcomesOf(work).continuationContext = [
        ...(effect.continuationContext ? [effect.continuationContext] : []),
        `The previous run stopped at a usage limit.`,
        ...(value.output ? [`Its partial reply was:\n${value.output}`] : []),
      ].join("\n\n");
      return;
    }
    outcomesOf(work).continuationContext = null;
    outcomesOf(work).implementation = value;
    // The commit both checks are lent: what this attempt left on the branch.
    outcomesOf(work).implemented = { repo: ticket.repo, revision: await git.headSha(ticket.repo, work.record.id) };
  },

  "open-pull-request": async (scope, work) => {
    // The base is the repository's own: the mapping reached this workflow
    // beside the fallback it overrides, and the host is told only what
    // was named — an absent base keeps the forge's own default.
    outcomesOf(work).pullRequestNumber = await scope.ports["code-host"].openPullRequest({
      repo: work.observation.ticket.repo,
      branch: branchOf(work.observation.ticket),
      title: pullRequestTitle(work.observation.ticket),
      base: baseBranchFor(scope.checkouts.layout, work.observation.ticket.repo),
      // Empty by convention. The ticket is the description.
      body: "",
    });
  },

  // The thread id the action carries is all the call needs.
  "resolve-review-thread": async (scope, _work, effect) => {
    await scope.ports["code-host"].resolveReviewThread(effect.threadId);
  },

  "address-threads": async (scope, work, effect) => {
    const { git } = scope.checkouts;
    const threads = (work.observation.pullRequest?.threads ?? []).filter((thread) =>
      effect.threadIds.includes(thread.id),
    );
    const ticket = work.observation.ticket;
    // The pull request's own branch: one found by its title — a ticket
    // renamed since, or opened by the operator from a branch of their
    // choosing — is not on the branch the ticket names now, and a fix
    // pushed there would never reach the threads it answered.
    const branch = work.observation.pullRequest?.headBranch ?? branchOf(ticket);
    await git.prepareBranch(ticket.repo, branch, work.record.id);
    const { value, run } = await judgeStep(scope.ports.agent, {
      prompt: threadPrompt(ticket, threads, effect.from, scope.config.reviewerHints as ReviewerHints, effect.discussion),
      cwd: await git.acquire(ticket.repo, work.record.id),
      context: { workId: work.record.id, step: "address-threads" },
      read: (answer) => readVerdicts(answer, threads),
      // An empty list is never read as "no comment needed answering": the
      // run did not complete, and the engine fails the action below.
      fallback: [],
    });
    refuseAnIncompleteRun("address-threads", run);
    await git.commitAndPush(ticket.repo, branch, `${ticket.id}: address review comments`, work.record.id);
    outcomesOf(work).verdicts = value;
  },

  // Read-only and moving nothing: the agent answers on the work's branch, the
  // answer goes back to the thread, and what was said is remembered so the
  // decision can carry it. Nothing is committed and no state changes.
  "discuss": async (scope, work, effect) => {
    const { git } = scope.checkouts;
    const { conversation } = scope.ports;
    const ticket = work.observation.ticket;
    if (!conversation) {
      throw new Error(`${work.record.id} has a discussion to answer and no conversation is mounted to answer it in`);
    }
    // Without a worktree the checkout is shared, and another ticket may have
    // moved it while this one waited: the work's own branch is put back
    // first, the way every step that reads the work's code does.
    await git.prepareBranch(ticket.repo, work.observation.pullRequest?.headBranch ?? branchOf(ticket), work.record.id);
    const reply = await scope.ports.agent.ask(
      discussPrompt(ticket, effect.about, effect.thread, effect.turns, {
        clarification: effect.clarification,
        threads: (work.observation.pullRequest?.threads ?? []).filter((thread) => effect.threadIds?.includes(thread.id)),
      }),
      await git.acquire(ticket.repo, work.record.id),
      { workId: work.record.id, step: "discuss", brief: ticket.brief, readOnly: true },
    );
    refuseAnIncompleteRun("discuss", reply.run);
    const thread = await conversation.open(work.record.id, ticket.title);
    await conversation.post(thread, { text: reply.text });
    outcomesOf(work).discussed = {
      since: effect.since,
      upTo: effect.turns.at(-1)!.at,
      lines: [...effect.turns.map((turn) => `${turn.author} asked: ${turn.text}`), `You answered: ${reply.text}`],
    };
  },

  "assign-reviewer": async (scope, work, effect) => {
    await requestReview(scope, work, effect.host);
    outcomesOf(work).reviewer = effect.host;
  },

  "request-rereview": async (scope, work, effect) => {
    await requestReview(scope, work, effect.host);
  },

  "escalate": async (scope, work, effect) => {
    const followUpTicketId = await scope.ports.tracker.createFollowUp({
      parentTicketId: work.observation.ticket.id,
      title: `FUP ${work.observation.ticket.id}: review comments need a decision`,
      body: effect.reason,
    });

    outcomesOf(work).escalation = {
      reason: effect.reason,
      askedAt: scope.ctx.now().toISOString(),
      followUpTicketId,
    };

    await scope.announce(`${work.record.id} is parked, ${followUpTicketId} has the details.`);
  },

  "hand-off-to-qa": async (scope, work, effect) => {
    await scope.ports.tracker.setStatus(work.observation.ticket.id, scope.config.qaStatusName);
    await scope.ports.tracker.assign(work.observation.ticket.id, effect.tracker);
  },

  // Only worth saying, so a channel that fails never costs the work a move.
  "announce": async (scope, _work, effect) => {
    await scope.announce(effect.text);
  },

  // Not swallowed the way an announcement is: a turn nobody heard is a
  // write nobody makes, so a failure here fails the action and the look is
  // tried again. Only a turn that was said is recorded as said.
  "hand-over": async (scope, work, effect) => {
    await sayToOperator(
      { conversation: scope.ports.conversation, notifier: scope.ports.notifier },
      {
        text: effect.turns.map((turn) => describeWrite(scope, turn.write, work)).join("\n\n"),
        workId: work.record.id,
        title: work.observation.ticket.title,
        state: work.record.state,
      },
    );
    const outcomes = outcomesOf(work);
    outcomes.handedOver = effect.turns.map((turn) => turn.key);
    outcomes.handedOverAt = scope.ctx.now().toISOString();
    for (const { write } of effect.turns) {
      if (write.type === "assign-reviewer") outcomes.reviewer = write.host;
      if (write.type === "escalate") outcomes.escalation = { reason: write.reason, askedAt: scope.ctx.now().toISOString() };
    }
  },
};

/**
 * The ticket a work id stands for, in the repository the id names.
 *
 * A ticket in several repositories is one work item per repository, and
 * the id says which: `PROJ-1@owner/name`. Every tracker call still uses the
 * ticket's own id; only the repository the work happens in changes.
 */
async function requireTicket(scope: Scope, workId: string): Promise<Ticket> {
  const { ticketId, repo } = splitWorkId(workId);
  const found = await scope.ports.tracker.get(ticketId);
  if (!found) {
    throw new Error(`${ticketId} is not in the tracker any more`);
  }
  // The tracker's membership is kept before the repository is overridden:
  // a ticket whose last label went is back in its team's repository alone,
  // and an item for another repository must still see that it left.
  return repo ? { ...found, repo, repos: found.repos ?? [found.repo] } : found;
}

/**
 * The ticket with its brief resolved, when it has one.
 *
 * Read here rather than at discovery so a revision between ticks reaches
 * the second tick as the current text: the record never holds a copy, and
 * a step that needs the brief again re-observes, the way every other field
 * here is re-read rather than replayed. A ticket that references no brief,
 * or references one the store does not hold, is returned as it arrived —
 * an absent brief is a state, not an error.
 */
async function requireTicketWithBrief(scope: Scope, workId: string): Promise<Ticket> {
  const ticket = await requireTicket(scope, workId);
  const briefs = scope.ports.brief;
  if (!ticket.briefId || !briefs) return ticket;

  const record = await briefs.get(ticket.briefId);
  if (!record) return ticket;

  return { ...ticket, brief: renderBrief(record).text };
}

async function requestReview(scope: Scope, work: Work, host: string): Promise<void> {
  const number = work.observation.pullRequest?.number ?? work.record.pullRequestNumber;
  if (number === undefined) {
    throw new Error(`${work.record.id} has no pull request to request a review on`);
  }
  await scope.ports["code-host"].requestReview(work.observation.ticket.repo, number, host);
}

/**
 * The ticket's pull request: by its branch, and — once one exists — by the
 * id in its title, so a ticket renamed since is still found. At `PR_OPEN`
 * only when the operator opens it, because they may open it from another
 * branch; the machine opens it from this one and has nothing to search for.
 */
async function pullRequestFor(scope: Scope, ticket: Ticket, state: TicketRecord["state"]): Promise<PullRequestView | null> {
  const host = scope.ports["code-host"];
  const byBranch = await host.findPullRequest(ticket.repo, branchOf(ticket));
  if (byBranch || BEFORE_A_PULL_REQUEST.includes(state)) return byBranch;
  if (state === "PR_OPEN" && scope.policy.writes !== "operator") return byBranch;
  return (await host.findPullRequestMentioning?.(ticket.repo, ticket.id)) ?? null;
}

/**
 * What was said back to a question or an escalation, read where it was
 * asked: the work's thread, or the ticket.
 *
 * With the writes handed to the operator and no thread, the operator
 * answers on the ticket with their own account — the same account this
 * machine reads the tracker as, which the tracker reports as the machine's
 * own. In that mode the machine wrote nothing on the ticket, so every
 * comment there is the operator's, and is read as one.
 */
async function answersFor(
  scope: Scope,
  current: TicketRecord,
  ticket: Ticket,
): Promise<Pick<Observation, "conversation" | "escalationAnswered">> {
  const { tracker } = scope.ports;
  const awaitingAnswer = current.state === "CLARIFYING" && Boolean(current.triage);
  const awaitingOwner = Boolean(current.escalation && !current.escalation.resolvedAt);
  if (!awaitingAnswer && !awaitingOwner) return { conversation: [], escalationAnswered: false };

  const since = awaitingAnswer ? current.triage!.at : current.escalation!.askedAt;
  const said = await saidSince(scope, current.id, ticket, since);
  // A button carries the question it answered. A press from an earlier wait
  // is evidence for that earlier question, never an escalation decision.
  const relevant = said?.filter((reply) => !reply.answer || (awaitingAnswer && current.triage!.askedQuestions.includes(reply.answer.ask)));
  const escalationAnswered = awaitingOwner && (relevant ? decided(relevant, scope.policy) : await tracker.hasReplyAfter(ticket.id, since));
  // The ticket's comments are read once there is an answer in them, not on
  // every poll of a wait: the owner's words are what the resumed step acts on.
  return {
    conversation: relevant ?? (awaitingAnswer || escalationAnswered ? await tracker.comments(ticket.id, since) : []),
    escalationAnswered,
  };
}

/**
 * Everything said back since a turn, where only the operator can have
 * said it: the work's thread, or — with the writes handed over — the
 * ticket. Null where the machine comments on the ticket too, and the
 * tracker's own reading of who wrote what is the one to trust.
 */
async function saidSince(scope: Scope, workId: string, ticket: Ticket, since: string): Promise<Said[] | null> {
  if (scope.ports.conversation) return repliesFor(scope.ports.conversation, workId, ticket.title, since);
  if (scope.policy.writes !== "operator") return null;
  return (await scope.ports.tracker.comments(ticket.id, since)).map((comment) => ({ ...comment, fromAmy: false }));
}

/**
 * Whether the ticket already sits in QA, and — at the handoff, for a ticket
 * in several repositories — whether each one merged.
 */
async function whereItStands(scope: Scope, ticket: Ticket, state: TicketRecord["state"]) {
  return {
    retired: !(ticket.repos ?? [ticket.repo]).includes(ticket.repo),
    inQa: ticket.status === scope.config.qaStatusName,
    ...(state === "QA_HANDOFF" && (ticket.repos?.length ?? 0) > 1 ? { repositories: await mergedIn(scope, ticket) } : {}),
  };
}

/**
 * Each of the ticket's repositories, and whether its pull request merged.
 *
 * Read by the ticket's id, because the other repositories' pull requests
 * belong to other work items. A host that cannot find one that way is
 * refused by name: reading "cannot tell" as "not merged" would hold the
 * ticket at the handoff for ever.
 */
async function mergedIn(scope: Scope, ticket: Ticket) {
  const find = requireMergeLookup(scope, ticket);
  return Promise.all(
    (ticket.repos ?? []).map(async (repo) => ({ repo, merged: Boolean((await find(repo, ticket.id))?.merged) })),
  );
}

function requireMergeLookup(scope: Scope, ticket: Ticket) {
  const host = scope.ports["code-host"];
  if (!host.findPullRequestMentioning) {
    throw new Error(
      `${ticket.id} is in ${(ticket.repos ?? []).join(" and ")}, and the mounted code host cannot find a pull request by a ticket's id, so it cannot say when every one has merged`,
    );
  }
  return host.findPullRequestMentioning.bind(host);
}

/** What the operator is asked to do, in words they can act on from a phone. */
function describeWrite(scope: Scope, write: WriteEffect, work: Work): string {
  const ticket = work.observation.ticket;
  const words = {
    ticket,
    pr: work.observation.pullRequest,
    where: scope.ports.conversation ? "in this thread" : `on ${ticket.url}`,
    base: baseBranchFor(scope.checkouts.layout, ticket.repo),
    qaStatusName: scope.config.qaStatusName,
  };
  return (WRITE_WORDS[write.type] as (write: WriteEffect, words: Words) => string)(write, words);
}

/**
 * The repository both checks run in, held before they start. An
 * implementation this version made recorded it with its commit; one an older
 * version made did not, and the checks would have no repository to run in.
 */
function toTheChecks(record: TicketRecord, observation: Observation, moved: Moved | null): TicketRecord {
  if (moved?.to !== "checks" || record.implemented) return record;
  return { ...record, implemented: { repo: observation.ticket.repo } };
}

interface Words {
  ticket: Ticket;
  pr: PullRequestView | null;
  where: string;
  base: string;
  qaStatusName: string;
}

/** One sentence per write, so a new write does not build until it can be said. */
const WRITE_WORDS: { [K in WriteEffect["type"]]: (write: Extract<WriteEffect, { type: K }>, words: Words) => string } = {
  "ask-question": (write, { ticket, where }) =>
    [`${ticket.id} needs an answer before I can start. Answer ${where}:`, numberedQuestions(write.questions)].join("\n"),
  "escalate": (write, { ticket, where }) => `${ticket.id} needs your call, answer ${where}: ${write.reason}`,
  "open-pull-request": (_write, { ticket, base }) =>
    `Open a pull request for ${ticket.id} in ${ticket.repo}, from ${branchOf(ticket)} into ${base}, titled "${pullRequestTitle(ticket)}". I carry on once I see it.`,
  "resolve-review-thread": (write, { ticket, pr }) => {
    const thread = pr?.threads.find((candidate) => candidate.id === write.threadId);
    const on = thread?.path ? `on ${thread.path} ` : "";
    const about = thread ? ` (${thread.body.split("\n")[0]})` : "";
    return `Resolve the review thread ${on}in ${pr?.url ?? ticket.repo}: the change answered it.${about}`;
  },
  "assign-reviewer": (write, { ticket, pr }) => `Request a review of ${pr?.url ?? ticket.id} from ${write.host}.`,
  "request-rereview": (write, { ticket, pr }) => `Ask ${write.host} to review ${pr?.url ?? ticket.id} again: every comment is addressed.`,
  "hand-off-to-qa": (write, { ticket, qaStatusName }) => `Move ${ticket.id} to ${qaStatusName} and assign it to ${write.tracker}: ${ticket.url}`,
};

/** The states before a pull request is expected, where none is found by title either. */
const BEFORE_A_PULL_REQUEST: readonly TicketRecord["state"][] = [
  "DISCOVERED",
  "CLARIFYING",
  "READY",
  "IMPLEMENTING",
  "checks",
  "verdict",
];

/**
 * `PROJ-1@owner%2Fname` is PROJ-1 in owner/name; a bare id names no
 * repository. The repository is encoded because a work id is a file name in
 * the store, the queue and the inbox, and a slash in one is a directory.
 */
export function workIdFor(ticketId: string, repo: string): string {
  return `${ticketId}@${encodeURIComponent(repo)}`;
}

export function splitWorkId(workId: string): { ticketId: string; repo?: string } {
  const at = workId.indexOf("@");
  if (at === -1) return { ticketId: workId };
  return { ticketId: workId.slice(0, at), repo: decodeURIComponent(workId.slice(at + 1)) };
}

function repliesFor(conversation: Conversation, workId: string, title: string, since: string): Promise<Said[]> {
  return conversation.open(workId, title).then((thread) => conversation.replies(thread, since)).then((replies) =>
    replies.map((reply) => ({
      author: reply.author,
      body: [reply.text, ...reply.files.map((file) => `Attachment: ${file}`)].filter(Boolean).join("\n"),
      at: reply.at,
      fromAmy: false,
      ...(reply.kind ? { kind: reply.kind } : {}),
      ...(reply.answer ? { answer: reply.answer, kind: "decision" as const } : {}),
    })),
  );
}

/** Text fallback for adapters that cannot render asks, and tracker comments. */
function numberedQuestions(questions: readonly import("./agent-steps.js").TriageQuestion[]): string {
  return questions.map((question, index) => {
    const text = questionText(question);
    return typeof question === "string"
      ? `- ${text}`
      : `${index + 1}. ${text}\n${question.answers.map((answer, answerIndex) => `   ${answerIndex + 1}. ${answer}`).join("\n")}`;
  }).join("\n");
}

function askFor(question: Exclude<import("./agent-steps.js").TriageQuestion, string>): Ask {
  if (question.answers[0] === "approve" && question.answers[1] === "reject" && question.answers.length === 2) {
    return { id: question.prompt, prompt: question.prompt, form: "approval", answers: ["approve", "reject"] };
  }
  return { id: question.prompt, prompt: question.prompt, form: "choice", answers: question.answers };
}

/**
 * Fails an action whose agent run did not complete.
 *
 * By the time this is reached, a relay has already tried every harness and
 * model it was given, so there is nowhere left to go and the action has to
 * fail rather than store an answer nobody gave.
 *
 * `implement` is deliberately not one of these: an attempt that did not hold
 * is a first-class outcome there, and the machine retries it with the reason
 * attached. `triage` and `address-threads` have no such outcome, and taking
 * their empty value as an answer would park a ticket waiting on a question
 * that was never asked, or drop a review comment nobody replied to.
 */
function refuseAnIncompleteRun(action: string, run: AgentRun): void {
  if (run.outcome === "completed") return;

  throw new Error(
    `${action} did not complete: ${run.outcome} on ${run.harness}` +
      `${run.model ? ` (${run.model})` : ""}${run.output ? `\n\n${run.output}` : ""}`,
  );
}

import { ReviewThread, Ticket } from "@amykit/core";

/**
 * This workflow's steps, written on the agent's one method.
 *
 * The prompts, the answers' shapes and how they are read used to be the
 * agent port's own methods, which put this workflow's lifecycle into every
 * workflow's contract. They are this workflow's, exported for another
 * workflow that wants the same steps. See docs/design/an-agent-only-answers.md.
 */

/** What one read of a ticket concluded. */
export interface TriageOutcome {
  /** True when the ticket can be implemented as written. */
  clear: boolean;
  questions: TriageQuestion[];
  at: string;
  /**
   * The questions the machine asked on the ticket for this ticket to be
   * read again.
   *
   * Recorded beside the questions rather than re-derived from history, so a
   * second look can tell its own words from new information without reading
   * anything but the record and the conversation.
   */
  askedQuestions: string[];
}

/** A triage question may offer a closed, single-choice answer set. */
export type TriageQuestion = string | { prompt: string; answers: string[] };

/** What one judged review comment concluded. */
export interface ThreadVerdict {
  threadId: string;
  /** `fixed` means the code changed. `disagreed` means it needs the owner. */
  verdict: "fixed" | "disagreed";
  note: string;
}

/** Guidance appended when answering a particular reviewer, by host login. */
export type ReviewerHints = Readonly<Record<string, string>>;

/**
 * The branch the tracker derived for a ticket, or a refusal naming the field.
 *
 * This workflow opens the branch the tracker named, because the tracker links
 * the pull request by it. A tracker that derives none cannot drive this
 * workflow, and saying so beats inventing a branch the tracker will not link.
 */
export function branchOf(ticket: Ticket): string {
  if (ticket.branchName) return ticket.branchName;
  throw new Error(
    `${ticket.id} has no \`branchName\`: ticket-to-qa works on the branch its tracker derives, and this tracker derived none`,
  );
}

export function triagePrompt(ticket: Ticket, conversation?: readonly string[]): string {
  return [
    `You are deciding whether a ticket can be implemented as written.`,
    ``,
    `Ticket ${ticket.id}: ${ticket.title}`,
    `Tracker: ${ticket.url}`,
    ...briefLines(ticket),
    ...bodyLines(ticket),
    ...labelLines(ticket),
    ...conversationLines(conversation),
    `Read enough of this repository to judge it. Answer with a`,
    `single JSON object and nothing else:`,
    ``,
    `{"clear": true}`,
    ``,
    `if you could start implementing right now, or:`,
    ``,
    `{"clear": false, "questions": ["...", {"prompt": "...", "answers": ["...", "..."]}]}`,
    ``,
    `listing only questions that genuinely block the work. A question you`,
    `could answer yourself by reading the code is not a blocking question.`,
    `A question already answered in the conversation above is not a`,
    `question: an answer to an earlier question is part of the ticket.`,
  ].join("\n");
}

/** Reads a triage answer; the questions asked are recorded so they are never asked twice. */
export function readTriage(answer: unknown, at: string): TriageOutcome {
  const reply = answer as { clear?: unknown; questions?: unknown };
  const questions = reply.clear === true ? [] : readQuestions(reply.questions);
  return { clear: reply.clear === true, questions, askedQuestions: questions.map(questionText), at };
}

function readQuestions(value: unknown): TriageQuestion[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((question): TriageQuestion[] => {
    if (typeof question === "string") return [question];
    if (!question || typeof question !== "object" || typeof (question as { prompt?: unknown }).prompt !== "string") return [];
    const { prompt, answers } = question as { prompt: string; answers?: unknown };
    return [hasChoices(prompt, answers) ? { prompt, answers } : prompt];
  });
}

/** A structured ask needs words for both its question and every selectable answer. */
function hasChoices(prompt: string, answers: unknown): answers is string[] {
  return prompt.trim().length > 0 &&
    Array.isArray(answers) &&
    answers.length >= 2 && answers.length <= 10 &&
    answers.every((answer) => typeof answer === "string" && answer.trim().length > 0) &&
    new Set(answers).size === answers.length;
}

export function questionText(question: TriageQuestion): string {
  return typeof question === "string" ? question : question.prompt;
}

/** A triage that could not be read: not clear, and nothing to ask. */
export function unreadTriage(at: string): TriageOutcome {
  return { clear: false, questions: [], askedQuestions: [], at };
}

export function implementPrompt(
  ticket: Ticket,
  retryContext?: string,
  continuationContext?: string,
  conversation?: readonly string[],
  discussion?: readonly string[],
): string {
  return [
    `Implement this ticket in the current repository.`,
    ``,
    `Ticket ${ticket.id}: ${ticket.title}`,
    `Tracker: ${ticket.url}`,
    ...briefLines(ticket),
    ...bodyLines(ticket),
    ...labelLines(ticket),
    ...conversationLines(conversation),
    ...decisionLines(discussion),
    ...(continuationContext
      ? [
          ``,
          `Continue the half-finished implementation already in this working tree.`,
          continuationContext,
          `Inspect the tree before changing it; keep work that is already correct.`,
        ]
      : []),
    ...(retryContext
      ? [
          ``,
          `A previous attempt did not hold. This is what went wrong, verbatim:`,
          ``,
          retryContext,
          ``,
          `Fix the underlying cause. Do not discard work that was already correct.`,
        ]
      : []),
    ``,
    `Follow the conventions already in this repository. Do not commit: that is`,
    `handled for you.`,
  ].join("\n");
}

export function threadPrompt(
  ticket: Ticket,
  threads: readonly ReviewThread[],
  from: "automated" | "human",
  reviewerHints: ReviewerHints = {},
  discussion?: readonly string[],
): string {
  const hints = [
    ...new Set(
      threads
        .map((thread) => reviewerHints[thread.author.toLowerCase()])
        .filter((hint): hint is string => Boolean(hint)),
    ),
  ];

  return [
    from === "automated"
      ? `An automated reviewer left comments on the pull request for this ticket.`
      : `A human reviewer left comments on the pull request for this ticket.`,
    ``,
    `Ticket ${ticket.id}: ${ticket.title}`,
    ...briefLines(ticket),
    ...bodyLines(ticket),
    ...labelLines(ticket),
    `Comments:`,
    ...threads.flatMap(threadLines),
    ...(hints.length ? [``, `Reviewer notes:`, ...hints.map((hint) => `- ${hint}`)] : []),
    ...decisionLines(discussion),
    ``,
    `A later comment in a thread answers the earlier ones, and the last`,
    `comment says who the thread is waiting on. Answer the thread as it`,
    `stands now, not as its first comment left it.`,
    ``,
    `For each comment, either change the code or say why you disagree. Do not`,
    `argue on the pull request. Do not commit: that is handled for you.`,
    ``,
    `Then answer with a single JSON object and nothing else:`,
    ``,
    `{"verdicts": [{"threadId": "...", "verdict": "fixed", "note": "what you changed"}]}`,
    ``,
    `Use "disagreed" only when you did not change the code, and say why in the`,
    `note. A disagreement goes to the ticket owner to settle, so be specific.`,
  ].join("\n");
}

/**
 * Answers somebody's turns in a discussion about work that is waiting on
 * them. The answer goes back to the thread as written, so it is prose; and
 * nothing is changed, because nothing has been decided.
 */
export function discussPrompt(
  ticket: Ticket,
  about: string,
  thread: readonly string[],
  turns: readonly { author: string; text: string }[],
  settled: { clarification?: readonly string[]; threads?: readonly ReviewThread[] } = {},
): string {
  return [
    `This work is waiting on a person, and they are discussing it with you before they decide.`,
    ``,
    `Ticket ${ticket.id}: ${ticket.title}`,
    `Tracker: ${ticket.url}`,
    ...briefLines(ticket),
    ...bodyLines(ticket),
    ...labelLines(ticket),
    ``,
    `What the work is waiting on:`,
    ``,
    about,
    ...(settled.threads?.length ? [``, `The review comments it is about:`, ...settled.threads.flatMap(threadLines)] : []),
    ...conversationLines(settled.clarification),
    ...(thread.length ? [``, `The discussion so far:`, ...thread.map((line) => `- ${line}`)] : []),
    ``,
    `What they said now:`,
    ...turns.map((turn) => `- ${turn.author}: ${turn.text}`),
    ``,
    `Answer them in plain prose, as a reply in the thread. Read this repository`,
    `as much as you need to, but change nothing and commit nothing: this is a`,
    `discussion, and the work resumes only when they decide.`,
  ].join("\n");
}

/**
 * One review thread as a conversation, not one comment: what follows the
 * opening comment is a correction of it or an answer to it, oldest first —
 * the last one says who is being waited on.
 */
function threadLines(thread: ReviewThread): string[] {
  return [
    `\n[${thread.id}] ${thread.author} said:\n${thread.body}`,
    ...thread.comments.slice(1).map((comment) => `  - ${comment.author} replied:\n${comment.body}`),
  ];
}

/**
 * Reads the verdicts, one per thread asked about.
 *
 * A comment the agent did not answer is not silently dropped. It goes to the
 * owner, because an unanswered review comment is the one thing that must
 * never disappear.
 */
export function readVerdicts(answer: unknown, threads: readonly ReviewThread[]): ThreadVerdict[] {
  const given = (answer as { verdicts?: ThreadVerdict[] }).verdicts ?? [];
  return threads.map((thread) => {
    const verdict = given.find((v) => v.threadId === thread.id);
    return {
      threadId: thread.id,
      verdict: verdict?.verdict ?? "disagreed",
      note: verdict?.note ?? "the agent did not answer this comment",
    };
  });
}

/**
 * The current brief the ticket's work belongs to, when it has one.
 *
 * Rendered rather than referenced: what a step must judge is what the brief
 * says *now*. A ticket with no brief carries none, and the prompt is
 * unchanged.
 */
function briefLines(ticket: Ticket): string[] {
  if (!ticket.brief) return [];
  return [
    `The current brief for the feature this ticket belongs to:`,
    ``,
    ticket.brief,
    ``,
    `Answer for the brief as it stands above, not for what the ticket`,
    `title alone says.`,
  ];
}

/** A ticket with no body says so, so the agent asks for one rather than guessing. */
function bodyLines(ticket: Ticket): string[] {
  return [``, ticket.body ?? `(this ticket has no description)`];
}

/** What the team says the ticket *is*; most carry no label and say nothing. */
function labelLines(ticket: Ticket): string[] {
  if (ticket.labels.length === 0) return [];
  return [`Labels: ${ticket.labels.join(", ")}`];
}

/** What the owner concluded after a discussion, so the step acts on that and not the first thing said. */
function decisionLines(discussion?: readonly string[]): string[] {
  if (!discussion || discussion.length === 0) return [];
  return [
    ``,
    `The owner was asked to decide, and discussed it first. The whole discussion, oldest first;`,
    `the last line is the decision, and it is what you act on:`,
    ...discussion.map((line) => `- ${line}`),
  ];
}

/** The conversation so far, so a question already answered is not asked again. */
function conversationLines(conversation?: readonly string[]): string[] {
  if (!conversation || conversation.length === 0) return [];
  return [``, `The conversation on the ticket, so far:`, ...conversation.map((line) => `- ${line}`)];
}

import { ReplyKind } from "@amykit/core";
import { DiscussionTurn, Effect } from "./effects.js";
import { Policy, Said } from "./observation.js";
import { Discussion, TicketRecord } from "./record.js";

/**
 * A reply is a turn in a discussion or the decision that ends one, and the
 * work moves only on the decision. Pure, so the machine and the fold read a
 * reply the same way. See docs/design/a-question-is-not-an-answer.md.
 */

/** As the person marked it, or as the policy reads a reply nobody marked. */
export function readAs(said: Said, policy: Policy): ReplyKind {
  return said.answer ? "decision" : (said.kind ?? (policy.conversation === "discuss" ? "discussion" : "decision"));
}

/** Whether a person, not this machine, has decided. */
export function decided(said: readonly Said[], policy: Policy): boolean {
  return said.some((reply) => !reply.fromAmy && readAs(reply, policy) === "decision");
}

/** What was discussed in the wait that began at `since`; another wait's is not this one's. */
function discussedSince(record: TicketRecord, since: string): Discussion | undefined {
  return record.discussion?.since === since ? record.discussion : undefined;
}

/**
 * The discussion turns of this wait nobody has answered yet, as one action —
 * or null when there are none.
 */
export function discussing(
  record: TicketRecord,
  said: readonly Said[],
  policy: Policy,
  since: string,
  about: string,
): Extract<Effect, { type: "discuss" }> | null {
  const discussed = discussedSince(record, since);
  const turns = turnsOf(said).filter((reply) => readAs(reply, policy) === "discussion" && reply.at > (discussed?.upTo ?? ""));
  if (turns.length === 0) return null;
  return { type: "discuss", since, about, thread: discussed?.lines ?? [], turns: turns.map(turnOf) };
}

/** The whole discussion of a wait, attributed, with the decision last and marked as the one that settled it. */
export function decisionLines(record: TicketRecord, said: readonly Said[], policy: Policy, since: string): string[] {
  const decisions = turnsOf(said).filter((reply) => readAs(reply, policy) === "decision");
  const last = decisions.at(-1);
  return [
    ...discussionBefore(record, { conversation: said }, policy, since),
    ...decisions.slice(0, -1).map((reply) => `${reply.author} said: ${reply.body}`),
    ...(last ? [`${last.author} decided, and this settles it: ${last.body}`] : []),
  ];
}

/**
 * Everything discussed in this wait: what was answered, then the turns not
 * answered yet, attributed. A turn asked in the same breath as the decision
 * is carried unanswered rather than dropped.
 */
export function discussionBefore(
  record: TicketRecord,
  obs: { conversation: readonly Said[] },
  policy: Policy,
  since: string,
): string[] {
  const discussed = discussedSince(record, since);
  const open = turnsOf(obs.conversation)
    .filter((reply) => readAs(reply, policy) === "discussion" && reply.at > (discussed?.upTo ?? ""))
    .map((reply) => `${reply.author} asked: ${reply.body}`);
  return [...(discussed?.lines ?? []), ...open];
}

/** What a person said, oldest first; a reply nobody can attribute is not a turn. */
function turnsOf(said: readonly Said[]): Said[] {
  return said.filter((reply) => !reply.fromAmy && reply.author).sort((a, b) => a.at.localeCompare(b.at));
}

/**
 * What a resolved escalation concluded, for the steps after it — or nothing
 * while one is open, or when none was ever discussed.
 */
export function settledDiscussion(record: TicketRecord): { discussion?: string[] } {
  const decision = record.escalation?.resolvedAt ? record.escalation.decision : undefined;
  return decision?.length ? { discussion: decision } : {};
}

function turnOf(reply: Said): DiscussionTurn {
  return { at: reply.at, author: reply.author, text: reply.body };
}

import { planning } from "@amykit/core";
import { TriageQuestion } from "./agent-steps.js";
import { TicketState } from "./state.js";

/**
 * This workflow's typed view of the actions it composes.
 *
 * The core owns the catalogue of action names and how each one is dispatched.
 * What lives here is the payload each one carries in *this* workflow, which
 * is what lets the decision function stay type-checked while the core stays
 * ignorant of tickets, reviewers and pull requests.
 */
export type Effect =
  /** Read the ticket and decide whether it can be implemented as written. */
  | { type: "triage"; conversation?: string[] }
  | { type: "ask-question"; questions: TriageQuestion[] }
  | { type: "implement"; retryContext?: string; continuationContext?: string; conversation?: string[]; discussion?: string[] }
  | { type: "open-pull-request" }
  | { type: "resolve-review-thread"; threadId: string }
  | { type: "address-threads"; threadIds: string[]; from: "automated" | "human"; discussion?: string[] }
  /**
   * Answer the turns somebody took in the work's thread while it waits, and
   * nothing else: no state, no commit, no attempt. `since` names the wait
   * the turns belong to, and `thread` is what was said in it before them.
   */
  | {
      type: "discuss";
      since: string;
      about: string;
      thread: string[];
      turns: DiscussionTurn[];
      /** What the questions before the work settled, so it is not argued again. */
      clarification?: string[];
      /** The review threads an escalated disagreement is about, read from the pull request. */
      threadIds?: string[];
    }
  | { type: "assign-reviewer"; host: string }
  | { type: "request-rereview"; host: string }
  | { type: "escalate"; reason: string; threadIds: string[] }
  | { type: "hand-off-to-qa"; tracker: string }
  | { type: "announce"; text: string }
  /**
   * Writes handed to the operator instead of made, said in one message. Each
   * turn carries the write it stands for, so the runtime can say exactly
   * what to do, and a key, so the machine says each one once.
   */
  | { type: "hand-over"; turns: HandOverTurn[] };

/** The writes this workflow makes on the tracker or the code host. */
export type WriteEffect = Extract<
  Effect,
  {
    type:
      | "ask-question"
      | "escalate"
      | "open-pull-request"
      | "resolve-review-thread"
      | "assign-reviewer"
      | "request-rereview"
      | "hand-off-to-qa";
  }
>;

/** One turn a person took in a discussion, attributed. */
export interface DiscussionTurn {
  at: string;
  author: string;
  text: string;
}

export interface HandOverTurn {
  key: string;
  write: WriteEffect;
}

export const WRITE_EFFECTS: readonly WriteEffect["type"][] = [
  "ask-question",
  "escalate",
  "open-pull-request",
  "resolve-review-thread",
  "assign-reviewer",
  "request-rereview",
  "hand-off-to-qa",
];

export function isWrite(effect: Effect): effect is WriteEffect {
  return (WRITE_EFFECTS as readonly string[]).includes(effect.type);
}

export const { act, advance, wait, settled } = planning<TicketState, Effect>();

import { Plan, PullRequestView } from "@amykit/core";
import { Effect, HandOverTurn, WriteEffect, act, advance, isWrite, wait } from "./effects.js";
import { Observation, Policy } from "./observation.js";
import { TicketRecord } from "./record.js";
import { TicketState } from "./state.js";

/**
 * The same decision, with every write handed to the operator.
 *
 * Pure, and applied after `plan` rather than threaded through it, so the
 * lifecycle stays one function and this switch is one more. A write becomes a
 * turn: said once, under a key the record keeps, and followed by waiting
 * until the observation shows the effect — the pull request there, the
 * thread closed, the review requested, the status moved. A write that moves
 * the state anyway, a question or an escalation, is said on the move, and the
 * state it moves to already waits for the answer.
 */
export function handOver(decided: Plan, record: TicketRecord, obs: Observation, policy: Policy): Plan {
  if (decided.kind === "settled") return decided;
  // The plan carries this workflow's own effects; the core types them loosely.
  const effects = decided.effects as Effect[];
  const writes = effects.filter(isWrite);
  if (writes.length === 0) return decided;

  const others = effects.filter((effect) => !isWrite(effect));
  const turns = writes.map((write) => ({ key: keyFor(write, record, obs), write }));

  if (decided.kind === "advance" && writes.every(movesOnItsOwn)) {
    return advance(decided.to as TicketState, decided.why, ...others, handOverOf(turns));
  }

  return turnOrWait(turns, others, record, obs, policy);
}

/**
 * A write the state stays put for: said if it has not been, and waited on
 * until the observation shows it made if it has.
 */
function turnOrWait(turns: HandOverTurn[], others: Effect[], record: TicketRecord, obs: Observation, policy: Policy): Plan {
  const said = new Set(record.handedOver ?? []);
  const write = turns[0]!.write;
  if (write.type === "hand-off-to-qa" && handedToQa(obs, write.tracker)) {
    return advance("DONE", `${obs.ticket.id} is in QA and owned by ${write.tracker}, as the operator left it`, ...others);
  }
  if (write.type === "request-rereview" && said.has(turns[0]!.key)) {
    return observedReview(write.host, obs, record.handedOverAt?.[turns[0]!.key])
      ? advance("HUMAN_REVIEW", `${write.host} was asked to look again`, ...others)
      : wait(policy.pollBackoffMs, `waiting for the operator to ask ${write.host} to look again`, ...others);
  }

  const unsaid = turns.filter((turn) => !said.has(turn.key));
  if (unsaid.length === 0) {
    return wait(policy.pollBackoffMs, `waiting for the operator to ${describe(turns.map((turn) => turn.write))}`, ...others);
  }
  return act(`handing ${describe(unsaid.map((turn) => turn.write))} to the operator`, ...others, handOverOf(unsaid));
}

/**
 * A review the operator was asked to request, read off the forge until it is
 * there. Decided from the record, not the roster: the reviewer was chosen
 * when the turn was said, and the load that chose them has since moved.
 *
 * Asked by the reviewer-assignment planner after its own safety checks — red
 * or unfinished checks, a conflict, no pull request — and before it picks a
 * reviewer, so a request the operator made never carries a broken branch past
 * them.
 */
export function pendingReviewRequest(record: TicketRecord, obs: Observation, policy: Policy): Plan | null {
  if (policy.writes !== "operator" || !record.reviewer) return null;
  const key = `request-review@${record.reviewer}`;
  if (!(record.handedOver ?? []).includes(key)) return null;

  return observedReview(record.reviewer, obs, record.handedOverAt?.[key])
    ? advance("HUMAN_REVIEW", `${record.reviewer} was asked to review`)
    : wait(policy.pollBackoffMs, `waiting for the operator to request a review from ${record.reviewer}`);
}

/**
 * The review the operator was asked to request: pending on the forge, or
 * already submitted since they were asked. A review from before the turn is
 * the round that sent the work back, not an answer to this one.
 */
function observedReview(host: string, obs: Observation, since: string | undefined): boolean {
  const pr: PullRequestView | null = obs.pullRequest;
  if (!pr) return false;
  // Logins compared the way the forge treats them, without case, and
  // instants as instants: `12:00:00Z` sorts after `12:00:00.900Z` as text.
  const who = host.toLowerCase();
  if (pr.requestedReviewers.some((requested) => requested.toLowerCase() === who)) return true;
  const after = since === undefined ? Number.NaN : Date.parse(since);
  return pr.reviews.some((review) => review.author.toLowerCase() === who && Date.parse(review.submittedAt) > after);
}

/**
 * The QA handoff as it was asked for: the status moved and the owner the
 * handoff named assigned — the one in the turn that was said, not whoever
 * the roster names today. A tracker that does not say who a ticket is
 * assigned to leaves the status as the only thing there is to see.
 */
export function handedToQa(obs: Observation, owner: string = obs.roster.qa.tracker): boolean {
  if (!obs.inQa) return false;
  const assignee = obs.ticket.assignee;
  return assignee === undefined || assignee?.toLowerCase() === owner.toLowerCase();
}

/** A question and an escalation move the state, and the state they reach waits for the answer. */
function movesOnItsOwn(write: WriteEffect): boolean {
  return write.type === "ask-question" || write.type === "escalate";
}

function keyFor(write: WriteEffect, record: TicketRecord, obs: Observation): string {
  switch (write.type) {
    case "ask-question":
      return `ask-question@${record.triage?.at ?? obs.now.toISOString()}`;
    case "escalate":
      return `escalate@${obs.now.toISOString()}`;
    case "open-pull-request":
      return `open-pull-request@${obs.ticket.repo}`;
    case "resolve-review-thread":
      return `resolve@${write.threadId}`;
    case "assign-reviewer":
      return `request-review@${write.host}`;
    // Keyed by the round — how many times the work has come back to ask
    // again — not by the head: two rounds on one head, comments refused and
    // nothing pushed, are two turns, and the second must be said rather than
    // answered by the review the first one drew.
    case "request-rereview":
      return `request-review@${write.host}@round${record.history.filter((moved) => moved.to === "RE_REVIEW").length}`;
    // Keyed by its owner, so a roster that changes before the operator made
    // it says the new handoff instead of waiting on the old one.
    case "hand-off-to-qa":
      return `hand-off-to-qa@${write.tracker}`;
  }
}

function handOverOf(turns: HandOverTurn[]): Effect {
  return { type: "hand-over", turns };
}

function describe(writes: readonly WriteEffect[]): string {
  const names: Record<WriteEffect["type"], string> = {
    "ask-question": "ask the question",
    "escalate": "take the decision",
    "open-pull-request": "open the pull request",
    "resolve-review-thread": "resolve the answered threads",
    "assign-reviewer": "request the review",
    "request-rereview": "request the review again",
    "hand-off-to-qa": "hand the ticket to QA",
  };
  return [...new Set(writes.map((write) => names[write.type]))].join(" and ");
}

