/**
 * The two checks an implementation goes through, as two lanes of one fork:
 * the gate and the work's review of itself, side by side, against the same
 * commit. Each is a workflow of its own, called from `checks` in this
 * package's diagram, and returns what it found to the verdict.
 *
 * They used to run one after the other, and a change the gate refused went
 * back to the implementation without what the review would have said about
 * it. See `docs/design/a-workflow-runs-on-lanes.md`.
 */

/** What every check is called with: where the work is, whose it is, and the commit to check. */
const CHECK_INPUT = {
  repo: { type: "string", required: true, description: "the repository the work is in" },
  workId: { type: "string", required: true, description: "the work whose change is checked" },
  revision: { type: "string", description: "the commit to check, lent read-only; the work's own tree when absent" },
} as const;

type CheckInput = { repo: string; workId: string; revision?: string };

/** What a check found, whichever way it ended. */
export type Finding = AttemptOutcome & { revision?: string };

type GateRecord = WorkRecord & { state: "CHECKING" | "GREEN" | "RED"; input: CheckInput; result?: Finding };

/**
 * Where a check runs: its own tree, which the host lends detached at the
 * commit the lane was bound to, when a worktree is mounted to lend one; and
 * the work's own tree when not — a shared checkout is already on the work's
 * branch.
 */
async function treeFor(
  git: { acquire(repo: string, workId?: string): Promise<string> },
  worktree: Worktree | undefined,
  record: WorkRecord & { input: CheckInput },
): Promise<{ readonly path: string; readonly workId: string }> {
  const { repo, workId } = record.input;
  if (worktree && record.revision) return { path: await git.acquire(repo, record.id), workId: record.id };
  return { path: await git.acquire(repo, workId), workId };
}

export const gateLane = withDiagram(defineWorkflow({
  name: "ticket-gate",
  configSchema: {},
  policy: {},
  needs: { gate: port<Gate>(), worktree: optional<Worktree>() },
  input: CHECK_INPUT,
  output: {
    GREEN: (record: GateRecord): Finding => record.result!,
    RED: (record: GateRecord): Finding => record.result!,
  },
  decide: {
    CHECKING: (record: GateRecord) => {
      if (!record.result) return { kind: "act", effects: [{ type: "run-gate" }], why: "the gate has not run against this commit" };
      return record.result.ok
        ? { kind: "advance", to: "GREEN", effects: [], why: "the gate is green" }
        : { kind: "advance", to: "RED", effects: [], why: "the gate is red" };
    },
    GREEN: () => ({ kind: "settled", why: "the gate is green" }),
    RED: () => ({ kind: "settled", why: "the gate is red" }),
  },
  record: () => ({}),
  observe: async () => ({}),
  actions: {
    "run-gate": async (scope, work) => {
      const record = work.record as GateRecord;
      const tree = await treeFor(scope.checkouts.git, scope.ports.worktree, record);
      const outcome = await scope.ports.gate.run({ repo: record.input.repo, workId: tree.workId });
      work.outcomes.result = { ...outcome, ...(record.input.revision ? { revision: record.input.revision } : {}) };
    },
  },
  remember: (_scope, record: GateRecord, outcomes) => (outcomes.result ? { ...record, result: outcomes.result as Finding } : record),
}), `stateDiagram-v2
    [*] --> CHECKING
    CHECKING --> GREEN: the gate passed
    CHECKING --> RED: the gate failed
    GREEN --> [*]
    RED --> [*]
`, "ticket-gate.mmd");

type ReviewRecord = WorkRecord & { state: "REVIEWING" | "APPROVED" | "CHANGES_ASKED"; input: CheckInput & { ticketId: string }; result?: Finding & { verdict: "APPROVED" | "CHANGES_ASKED" } };

interface ReviewObservation {
  readonly id: string;
  readonly title: string;
  /** The brief as it reads now, so a revision between looks reaches the review. */
  readonly brief?: string;
}

type Asking = Agent & { ask(prompt: string, cwd: string, context?: AskContext): Promise<HarnessReply> };

/**
 * The verdict a review ends on: a line of its own saying `CHANGES_ASKED`
 * sends the work back; anything else is a review that found nothing to stop
 * it, which is what every review was before it could say so.
 */
export function reviewVerdict(text: string): "APPROVED" | "CHANGES_ASKED" {
  const asked = text.split("\n").some((line) => verdictWord(line).startsWith("CHANGES_ASKED"));
  return asked ? "CHANGES_ASKED" : "APPROVED";
}

/**
 * A line as a verdict reads, its markdown let go of: a bullet, a quote, a
 * heading, bold or code around it, and a `Verdict:` before it — an agent
 * writes the line it is asked for the way it writes any other.
 */
function verdictWord(line: string): string {
  const unmarked = (text: string) => text.replace(/^[\s>*_`#-]+/, "");
  return unmarked(unmarked(line).replace(/^verdict\s*:?/i, "")).toUpperCase();
}

export const selfReviewLane = withDiagram(defineWorkflow({
  name: "ticket-self-review",
  configSchema: {},
  policy: {},
  needs: { tracker: port<Tracker>(), agent: port<Asking>(), brief: optional<BriefStore>(), worktree: optional<Worktree>() },
  input: { ...CHECK_INPUT, ticketId: { type: "string", required: true, description: "the ticket the change is for" } },
  output: {
    APPROVED: (record: ReviewRecord): Finding => record.result!,
    CHANGES_ASKED: (record: ReviewRecord): Finding => record.result!,
  },
  decide: {
    REVIEWING: (record: ReviewRecord) => {
      if (!record.result) return { kind: "act", effects: [{ type: "self-review" }], why: "the change has not been read against what it was for" };
      return { kind: "advance", to: record.result.verdict, effects: [], why: record.result.verdict === "APPROVED" ? "the review found nothing to stop it" : "the review asked for changes" };
    },
    APPROVED: () => ({ kind: "settled", why: "approved" }),
    CHANGES_ASKED: () => ({ kind: "settled", why: "changes asked" }),
  },
  record: () => ({}),
  observe: async (scope, record): Promise<ReviewObservation> => {
    const ticketId = (record as ReviewRecord).input.ticketId;
    const ticket = await scope.ports.tracker.get(ticketId);
    if (!ticket) throw new Error(`${ticketId} is not in the tracker any more`);
    const brief = ticket.briefId && scope.ports.brief ? await scope.ports.brief.get(ticket.briefId) : null;
    return { id: ticket.id, title: ticket.title, ...(brief ? { brief: renderBrief(brief).text } : {}) };
  },
  actions: {
    // The work reads itself against the brief before a person is asked to,
    // in its own tree at the commit the gate checks too. The brief travels in
    // the context as well, the field every generic `ask` reads.
    "self-review": async (scope, work) => {
      const record = work.record as ReviewRecord;
      const ticket = work.observation as ReviewObservation;
      const tree = await treeFor(scope.checkouts.git, scope.ports.worktree, record);
      const reply = await scope.ports.agent.ask(
        [
          `The ticket ${ticket.id} was implemented in this repository. Review`,
          `the change at the current commit against what the work was for,`,
          `and say what a reviewer should look at first.`,
          `End with a line saying APPROVED if it is ready for a reviewer, or`,
          `CHANGES_ASKED and what has to change before it is.`,
          ...(ticket.brief ? [``, `The current brief for the feature this ticket belongs to:`, ``, ticket.brief] : []),
        ].join("\n"),
        tree.path,
        { workId: record.id, step: "self-review", brief: ticket.brief },
      );
      // A review that did not finish found nothing either way, so it never
      // ends the lane. Out of quota, it was not a try and waits; anything
      // else fails the look, the way every other agent step here does.
      if (reply.run.outcome === "rate-limited") {
        work.outcomes.waited = { notATry: true };
        return;
      }
      if (reply.run.outcome !== "completed") {
        throw new Error(`self-review did not complete: ${reply.run.outcome} on ${reply.run.harness}${reply.run.output ? `\n\n${reply.run.output}` : ""}`);
      }
      work.outcomes.result = {
        ok: true,
        output: reply.text,
        at: scope.ctx.now().toISOString(),
        verdict: reviewVerdict(reply.text),
        ...(record.input.revision ? { revision: record.input.revision } : {}),
      };
    },
  },
  remember: (_scope, record: ReviewRecord, outcomes) => (outcomes.result ? { ...record, result: outcomes.result as ReviewRecord["result"] } : record),
}), `stateDiagram-v2
    [*] --> REVIEWING
    REVIEWING --> APPROVED: nothing to stop it
    REVIEWING --> CHANGES_ASKED: it asks for changes
    APPROVED --> [*]
    CHANGES_ASKED --> [*]
`, "ticket-self-review.mmd");

import { Observation, Policy } from "./observation.js";
import { attemptsIn, looksIn, Plan, PullRequestView, ReviewThread } from "@amykit/core";
import { act, advance, settled, wait } from "./effects.js";
import {
  TicketRecord,
  disagreements,
  judgedThreadIds,
} from "./record.js";
import { DecidedState, TicketState } from "./state.js";
import {
  automatedReviewerSawHead,
  hasReviewedHead,
  unresolvedThreads,
} from "./review.js";
import { isConfirmedFor, leastLoadedReviewer } from "./roster.js";
import { handOver, handedToQa, pendingReviewRequest } from "./handover.js";
import { discussionBefore, discussing, readAs, settledDiscussion } from "./discussion.js";

/**
 * Decides the single next move for one ticket.
 *
 * Pure on purpose. Every branch below is a predicate over the record and the
 * observation, so the whole lifecycle can be driven in a test without a
 * tracker, a code host, a repository or an agent.
 */
export function plan(record: TicketRecord, obs: Observation, policy: Policy): Plan {
  if (record.state === "checks") {
    throw new Error(`${record.id} is in \`checks\`, which its lanes move: drive the mounted workflow, which composes them`);
  }
  const early = before(record, obs, policy);
  const decided = early ?? decide[record.state](record, obs, policy);
  return after(decided, record, obs, policy);
}

export function before(record: TicketRecord, obs: Observation, _policy: Policy): Plan | undefined {
  if (obs.retired && record.state !== "DONE") return retire(obs);
  return ranTheChecksInTurn(record);
}

/**
 * A record an older version saved in `CHECKED` or `SELF_REVIEW`, the two
 * states the checks were before they ran as lanes. Its implementation is
 * already done, so it goes straight to `checks` and is checked again in both
 * lanes — not back to the agent, which would pay for the same work twice, and
 * not on to a pull request on a check the record no longer explains.
 */
function ranTheChecksInTurn(record: TicketRecord): Plan | undefined {
  const state = record.state as string;
  if (state !== "CHECKED" && state !== "SELF_REVIEW") return undefined;
  return advance("checks", `${state} is where the checks ran before they ran as lanes; checking the work again in both`);
}

export function after(decision: Plan, record: TicketRecord, obs: Observation, policy: Policy): Plan {
  return policy.writes === "operator" ? handOver(decision, record, obs, policy) : decision;
}

type Planner = (record: TicketRecord, obs: Observation, policy: Policy) => Plan;

/**
 * Stops a work item whose repository left the ticket, where it stands.
 *
 * Settled rather than DONE: a terminal record is one discovery never offers
 * again, and the label may come back. Settling takes the item off the queue
 * and leaves its record mid-lifecycle, so while discovery does not offer it
 * nothing moves it, and the day it does the work resumes from where it was.
 * Whatever it already pushed or opened is left as it is.
 */
function retire(obs: Observation): Plan {
  return settled(`${obs.ticket.repo} is no longer one of ${obs.ticket.id}'s repositories; the work there stops where it is until it is again`);
}

/**
 * One planner per state. A record rather than a switch, so the compiler is
 * what proves no state was forgotten: a state added to `TicketState` and
 * not here does not build, and one drawn in `workflow.mmd` and not in
 * `TicketState` is a move the walkthrough refuses.
 */
export const decide: Record<DecidedState, Planner> = {
  DISCOVERED: (record) => planDiscovered(record),
  CLARIFYING: planClarifying,
  READY: () => advance("IMPLEMENTING", "nothing is blocking the implementation"),
  IMPLEMENTING: (record, _obs, policy) => planImplementing(record, policy),
  verdict: (record, _obs, policy) => planVerdict(record, policy),
  PR_OPEN: (_record, obs) => planPullRequestOpen(obs),
  COPILOT_WAIT: planAutomatedReviewWait,
  COPILOT_FIX: planAutomatedReviewFix,
  REVIEWER_ASSIGNED: planReviewerAssignment,
  HUMAN_REVIEW: planHumanReview,
  HUMAN_FIX: planHumanFix,
  ESCALATED: planEscalated,
  RE_REVIEW: (record) => planReReview(record),
  APPROVED: () => advance("QA_HANDOFF", "a human approved the current head"),
  QA_HANDOFF: planQaHandoff,
  DONE: () => settled("the ticket is in QA and owned by somebody else"),
};

function planDiscovered(record: TicketRecord): Plan {
  if (!record.triage) {
    return act("the ticket has not been read yet", { type: "triage" });
  }

  if (record.triage.clear) {
    return advance("READY", "the ticket can be implemented as written");
  }

  return advance(
    "CLARIFYING",
    `the ticket leaves ${record.triage.questions.length} question(s) open`,
    { type: "ask-question", questions: record.triage.questions },
  );
}

/**
 * What a reply on the ticket said, split by who wrote it.
 *
 * Amy's own comments are labelled as questions it already asked — they are
 * how the machine's account of the conversation and the record's agree, and
 * without the label a second look reads its own words as the answer it was
 * waiting for. A comment nobody can attribute is left out rather than guessed
 * at: the tracker is where `fromAmy` is settled, and a comment with no author
 * is a conversation with a hole in it, which is a finding rather than an
 * input.
 *
 * An answer from somebody is only news when it is not the machine's own
 * question quoted back — a tracker that copies the body into a reply, or a
 * system that quotes the thread, must not pass for an answer.
 */
function conversationLines(record: TicketRecord, conversation: Observation["conversation"]): string[] {
  const asked = new Set(record.triage?.askedQuestions ?? []);

  const lines: string[] = [];
  for (const comment of conversation) {
    if (comment.fromAmy) {
      if (asked.has(comment.body)) continue;
      asked.add(comment.body);
      lines.push(`You asked: ${comment.body}`);
    } else if (comment.author && (!asked.has(comment.body) || comment.answer)) {
      const answer = comment.answer
        ? `${comment.answer.ask}: ${comment.answer.chosen.join(", ")}`
        : comment.body;
      lines.push(`${comment.author} answered: ${answer}`);
    }
  }

  return lines;
}

/**
 * Keeps a closed answer only when it still belongs to this triage, and only
 * keeps the first answer for each ask. The workflow, not an adapter's memory,
 * owns that selection: replaying the same look yields the same answer, while
 * a stale button press cannot settle a newer triage.
 */
function selectedAnswers(record: TicketRecord, conversation: Observation["conversation"]): Observation["conversation"] {
  const questions = new Map<string, readonly string[]>();
  for (const question of record.triage?.questions ?? []) {
    if (typeof question !== "string") questions.set(question.prompt, question.answers);
  }

  const answered = new Set<string>();
  return conversation.filter((comment) => {
    if (!comment.answer) return true;
    const choices = questions.get(comment.answer.ask);
    const chosen = comment.answer.chosen;
    const valid = choices !== undefined && chosen.length > 0 && chosen.every((answer) => choices.includes(answer));
    if (!valid || answered.has(comment.answer.ask)) return false;
    answered.add(comment.answer.ask);
    return true;
  });
}

/**
 * Waiting on an answer to the questions the triage asked.
 *
 * A turn somebody takes in a discussion is answered in the thread and moves
 * nothing; the work goes back to the triage only on a decision, carrying
 * the discussion that came before it.
 */
function planClarifying(record: TicketRecord, obs: Observation, policy: Policy): Plan {
  const since = record.triage?.at ?? "";
  const conversation = selectedAnswers(record, obs.conversation);
  const decisions = conversation.filter((comment) => comment.fromAmy || readAs(comment, policy) === "decision");
  const answered = conversationLines(record, decisions);

  // Only a decision unblocks the wait. The discussion before it — answered,
  // or said in the same breath and not answered yet — goes to the triage with
  // it, so a decision that says "use that" still has "that" in front of it.
  if (answered.some((line) => line.includes("answered:"))) {
    return advance("READY", "the question in the work thread was answered", {
      type: "triage",
      conversation: [...discussionBefore(record, { conversation }, policy, since), ...answered],
    });
  }

  const discussion = discussing(record, conversation, policy, since, (record.triage?.askedQuestions ?? []).join("\n"));
  if (discussion) return act(`answering ${discussion.turns.length} turn(s) of a discussion before anything is decided`, discussion);

  // Re-asking is the defect this state used to be: a look without an answer
  // holds rather than posts the same words again. `CLARIFYING` cannot clear
  // because the ticket was touched — only because it was answered.
  return wait(policy.pollBackoffMs, "waiting for an answer in the work thread");
}

/**
 * An implementation only counts as current if it happened after the last gate
 * run. Without that check a red gate would bounce back into IMPLEMENTING,
 * find the old successful attempt still recorded, and go straight back to the
 * gate forever.
 */
function implementationIsCurrent(record: TicketRecord): boolean {
  const attempt = record.lastImplementation;
  if (!attempt) return false;
  if (!record.lastGate) return true;
  return attempt.at > record.lastGate.at;
}

/** Whether a check ran after the last implementation, and so is about it. */
function isCurrent(check: { at: string } | undefined, record: TicketRecord): boolean {
  if (!check) return false;
  if (!record.lastImplementation) return true;
  return check.at > record.lastImplementation.at;
}

/**
 * What the next implementation is told: everything both checks found about
 * the last one, in one round, so a change the gate refuses goes back with
 * what the review said about it too.
 */
function retryContextFor(record: TicketRecord): string | undefined {
  const found = checksFound(record);
  if (found.length > 0) return found.join("\n\n");
  if (record.lastImplementation && !record.lastImplementation.ok) {
    return record.lastImplementation.output;
  }
  return undefined;
}

/** What the gate refused and what the review said about the last implementation, each under its name. */
function checksFound(record: TicketRecord): string[] {
  const gate = record.lastGate;
  const review = record.lastSelfReview;
  const refused = isCurrent(gate, record) && !gate!.ok;
  const reviewed = isCurrent(review, record) && (refused || review!.verdict === "CHANGES_ASKED");
  return [
    ...(refused ? [`The gate said:\n${gate!.output}`] : []),
    ...(reviewed ? [`The review of the change said:\n${review!.output}`] : []),
  ];
}

function planImplementing(record: TicketRecord, policy: Policy): Plan {
  if (implementationIsCurrent(record) && record.lastImplementation?.ok) {
    return advance("checks", "the agent finished; the gate and the review decide if it holds");
  }

  const attempts = attemptsIn(record, "IMPLEMENTING");
  if (attempts >= policy.maxImplementAttempts) {
    return advance(
      "ESCALATED",
      `the agent failed ${attempts} times, this needs the owner`,
      {
        type: "escalate",
        reason: `Implementation failed ${attempts} times. Last output:\n${record.lastImplementation?.output ?? "none"}`,
        threadIds: [],
      },
    );
  }

  return act(`implementation attempt ${attempts + 1}`, {
    type: "implement",
    retryContext: retryContextFor(record),
    ...(record.continuationContext
      ? { continuationContext: record.continuationContext }
      : {}),
    ...(record.clarification?.length ? { conversation: record.clarification } : {}),
    ...settledDiscussion(record),
  });
}

/**
 * Where the gate and the self-review meet, each having checked the same
 * commit. Both clean is a pull request; either finding something sends the
 * implementation back with both findings at once, until the rounds run out.
 */
function planVerdict(record: TicketRecord, policy: Policy): Plan {
  const gate = record.lanes?.GATE?.end;
  const review = record.lanes?.SELF_REVIEW?.end;
  if (gate === "GREEN" && review === "APPROVED") {
    return advance("PR_OPEN", "the gate is green and the review found nothing to stop it");
  }

  const found = [gate === "RED" ? "the gate is red" : undefined, review === "CHANGES_ASKED" ? "the review asked for changes" : undefined]
    .filter((said) => said !== undefined)
    .join(" and ");
  const rounds = attemptsIn(record, "verdict");
  if (rounds >= policy.maxGateAttempts) {
    return advance("ESCALATED", `the checks found something across ${rounds} rounds`, {
      type: "escalate",
      reason: `The checks found something across ${rounds} rounds. Last time:\n${retryContextFor(record) ?? "nothing was said"}`,
      threadIds: [],
    });
  }

  // No effect here on purpose. IMPLEMENTING sees that the checks ran after
  // the last attempt, so it acts again and picks both up as its retry
  // context. That keeps every retry counted in exactly one place.
  return advance("IMPLEMENTING", `${found || "a check did not end clean"}, back to the agent with what both said`);
}

function planPullRequestOpen(obs: Observation): Plan {
  if (obs.pullRequest) {
    return advance("COPILOT_WAIT", `pull request #${obs.pullRequest.number} exists`);
  }
  return act("the branch has no pull request yet", { type: "open-pull-request" });
}

/** Guards a state that cannot mean anything without a pull request. */
function requirePullRequest(obs: Observation, state: TicketState): PullRequestView | Plan {
  if (!obs.pullRequest) {
    return advance("PR_OPEN", `${state} has no pull request to look at`);
  }
  return obs.pullRequest;
}

function isPlan(value: PullRequestView | Plan): value is Plan {
  return "kind" in value;
}

function outstanding(
  pr: PullRequestView,
  from: "automated" | "human",
  record: TicketRecord,
): readonly ReviewThread[] {
  const judged = judgedThreadIds(record);
  return unresolvedThreads(pr, from).filter((t) => !judged.includes(t.id));
}

function planAutomatedReviewWait(
  record: TicketRecord,
  obs: Observation,
  policy: Policy,
): Plan {
  const pr = requirePullRequest(obs, "COPILOT_WAIT");
  if (isPlan(pr)) return pr;

  if (!automatedReviewerSawHead(pr)) {
    return wait(
      policy.pollBackoffMs,
      `waiting for the automated reviewer to look at ${pr.headSha.slice(0, 7)}`,
    );
  }

  const open = outstanding(pr, "automated", record);
  if (open.length > 0) {
    return advance("COPILOT_FIX", `the automated reviewer left ${open.length} open thread(s)`);
  }

  return advance("REVIEWER_ASSIGNED", "the automated reviewer has nothing outstanding");
}

/**
 * Whether the change is too large to hand to an agent, and why.
 *
 * Pure and free: the size came back with the pull request, so refusing costs
 * nothing where making the call would have cost the most. Returns the
 * sentence rather than a boolean, because what a person needs to read in the
 * escalation is which ceiling was passed and by how much.
 */
function tooLargeForAnAgent(pr: PullRequestView, policy: Policy): string | null {
  const lines = pr.additions + pr.deletions;

  if (policy.maxPullRequestFiles > 0 && pr.changedFiles > policy.maxPullRequestFiles) {
    return `${pr.changedFiles} files changed, over the ${policy.maxPullRequestFiles} I will hand to an agent`;
  }
  if (policy.maxPullRequestLines > 0 && lines > policy.maxPullRequestLines) {
    return `${lines} lines changed, over the ${policy.maxPullRequestLines} I will hand to an agent`;
  }

  return null;
}
function planAutomatedReviewFix(record: TicketRecord, obs: Observation, policy: Policy): Plan {
  const pr = requirePullRequest(obs, "COPILOT_FIX");
  if (isPlan(pr)) return pr;

  const open = outstanding(pr, "automated", record);

  /**
   * Close what this machine answered and the forge still holds open, before
   * looking at anything left.
   *
   * The pool is every unresolved automated thread the forge reports, not the
   * unjudged remainder: a thread the record judged `fixed` drops out of
   * `outstanding`, and a state that only looked there would leave the way its
   * exit condition reads while the conversation was still open on the forge —
   * a judged thread is one the record has an opinion about, not one the forge
   * agrees is settled. The move is one act per thread judged `fixed`: the
   * code changed, so the conversation is over. One act per look, because the
   * next look sees the threads resolved and finds nothing more to close.
   */
  const answered = unresolvedThreads(pr, "automated").filter((t) =>
    record.judged.some((j) => j.threadId === t.id && j.verdict === "fixed"),
  );
  if (answered.length > 0) {
    return act(
      `closing ${answered.length} thread(s) the fix answered`,
      ...answered.map((t) => ({ type: "resolve-review-thread" as const, threadId: t.id })),
    );
  }

  if (open.length === 0) {
    return advance("COPILOT_WAIT", "every automated thread has been judged");
  }

  const tooLarge = tooLargeForAnAgent(pr, policy);
  if (tooLarge) return handBack(record, pr, policy, tooLarge, open.map((t) => t.id));

  return act(`addressing ${open.length} automated thread(s)`, {
    type: "address-threads",
    threadIds: open.map((t) => t.id),
    from: "automated",
    ...settledDiscussion(record),
  });
}

/**
 * Gives the review back to the ticket owner, once.
 *
 * `ESCALATED` already means "this needs the person whose ticket it is", so a
 * change nobody should automate lands in the state that already exists for
 * it rather than in one invented for size.
 */
function handBack(
  record: TicketRecord,
  pr: PullRequestView,
  policy: Policy,
  why: string,
  threadIds: string[],
): Plan {
  if (record.escalation && !record.escalation.resolvedAt) {
    return wait(policy.pollBackoffMs, `waiting on the owner: ${why}`);
  }

  return advance("ESCALATED", why, {
    type: "escalate",
    reason: `This pull request is bigger than I will work on unattended — ${why}. The review is yours: ${pr.url}`,
    threadIds,
  });
}

/**
 * What the forge already knows is wrong with the branch, and nothing else.
 *
 * Read before a person is asked, because review time is the one currency
 * here nobody can top up — the same reason the per-reviewer ceiling exists.
 * A reading of red checks, of a branch that will not merge, or of one sitting
 * on a base it has moved off, is a reading that has to be done again.
 *
 * No checks at all is not a complaint. A repository that runs none reports
 * exactly that, and a machine that read it as "not passing" would hold every
 * pull request for a verdict nobody is coming to give.
 */
function whatTheForgeSays(pr: PullRequestView): string | null {
  if (pr.checks?.state === "failing") return `the checks on ${pr.headSha.slice(0, 7)} are red`;
  if (pr.mergeState === "conflicting") return "the branch conflicts with its base";
  if (pr.mergeState === "behind") return "the branch is behind its base";
  return null;
}
/** The forge's complaint, handed to the owner once, the way size already is. */
function handBackBroken(
  record: TicketRecord,
  pr: PullRequestView,
  policy: Policy,
  why: string,
): Plan {
  if (record.escalation && !record.escalation.resolvedAt) {
    return wait(policy.pollBackoffMs, `waiting on the owner: ${why}`);
  }

  return advance("ESCALATED", why, {
    type: "escalate",
    reason: `I am not asking anybody to review this yet — ${why}. It is yours: ${pr.url}`,
    threadIds: [],
  });
}

function planReviewerAssignment(
  record: TicketRecord,
  obs: Observation,
  policy: Policy,
): Plan {
  const pr = requirePullRequest(obs, "REVIEWER_ASSIGNED");
  if (isPlan(pr)) return pr;

  // A verdict that has not arrived is not a bad one. Waiting costs a poll;
  // asking somebody to read what CI is about to fail costs their afternoon.
  //
  // Bounded, because a check that is configured and never reports leaves a
  // rollup that says `running` for ever, and an unbounded wait here is a
  // ticket that stops without anybody being told. The remote checks are a
  // gate, so they answer to the same ceiling the local one does.
  if (pr.checks?.state === "running") {
    const looks = looksIn(record, "REVIEWER_ASSIGNED");
    if (looks < policy.maxGateAttempts) {
      return wait(policy.pollBackoffMs, `the checks on ${pr.headSha.slice(0, 7)} have not finished`);
    }
    return handBackBroken(
      record,
      pr,
      policy,
      `the checks on ${pr.headSha.slice(0, 7)} never finished`,
    );
  }

  const broken = whatTheForgeSays(pr);
  if (broken) return handBackBroken(record, pr, policy, broken);

  const requested = pendingReviewRequest(record, obs, policy);
  if (requested) return requested;

  const firstLook = looksIn(record, "REVIEWER_ASSIGNED") === 0;

  if (!isConfirmedFor(obs.roster, obs.now)) {
    return holdAndSayOnce(
      firstLook,
      policy.rosterBackoffMs,
      `the roster was last confirmed on ${obs.roster.confirmedOn}, not today`,
      `Confirm today's reviewers and QA before I assign ${record.id}.`,
    );
  }

  const reviewer = leastLoadedReviewer(obs.roster, obs.reviewLoad);
  if (!reviewer) {
    return holdAndSayOnce(
      firstLook,
      policy.rosterBackoffMs,
      "every reviewer on the roster is marked unavailable",
      `No reviewer is available for ${record.id}.`,
    );
  }

  // Nobody else is emptier, so if this one is at the ceiling they all are.
  // The pull request stays open with no reviewer on it, which is the point:
  // the work is done and only somebody's attention is being rationed.
  const load = obs.reviewLoad[reviewer.host] ?? 0;
  if (load >= policy.maxOpenReviewsPerReviewer) {
    return holdAndSayOnce(
      firstLook,
      policy.pollBackoffMs,
      `every reviewer is carrying ${policy.maxOpenReviewsPerReviewer} open review(s) or more`,
      `${record.id} has a pull request open and nobody assigned: ` +
        `every reviewer is at ${policy.maxOpenReviewsPerReviewer} open review(s).`,
    );
  }

  return advance(
    "HUMAN_REVIEW",
    `${reviewer.host} carries the fewest open reviews (${load})`,
    { type: "assign-reviewer", host: reviewer.host },
  );
}

/**
 * Holds, and tells the operator once rather than on every look.
 *
 * The three reasons this state waits for are all somebody else's move, and a
 * message repeated every five minutes is a message nobody reads.
 */
function holdAndSayOnce(
  firstLook: boolean,
  retryAfterMs: number,
  why: string,
  text: string,
): Plan {
  return wait(retryAfterMs, why, ...(firstLook ? [{ type: "announce" as const, text }] : []));
}

function planHumanReview(record: TicketRecord, obs: Observation, policy: Policy): Plan {
  const pr = requirePullRequest(obs, "HUMAN_REVIEW");
  if (isPlan(pr)) return pr;

  const reviewer = record.reviewer;
  if (!reviewer) {
    return advance("REVIEWER_ASSIGNED", "no reviewer is recorded for this ticket");
  }

  if (!hasReviewedHead(pr, reviewer)) {
    return wait(
      policy.pollBackoffMs,
      `waiting for ${reviewer} to review ${pr.headSha.slice(0, 7)}`,
    );
  }

  const askedAgain = askedAgainAt(record);
  if (askedAgain !== undefined && !reviewedSince(pr, reviewer, askedAgain)) {
    return wait(policy.pollBackoffMs, `waiting for ${reviewer} to look again at ${pr.headSha.slice(0, 7)}`);
  }

  if (pr.reviewDecision === "APPROVED") {
    return advance("APPROVED", `${reviewer} approved the current head`);
  }

  const open = outstanding(pr, "human", record);
  if (open.length > 0) {
    return advance("HUMAN_FIX", `${reviewer} left ${open.length} open thread(s)`);
  }

  if (pr.reviewDecision === "CHANGES_REQUESTED") {
    return advance("RE_REVIEW", "every thread was judged, the review has to be redone");
  }

  return wait(policy.pollBackoffMs, `${reviewer} commented without deciding`);
}

/**
 * When this round of review was asked for again, if it was.
 *
 * Nothing pushed since the reviewer asked for changes leaves their review on
 * the head, and reading it as the answer to the request just made sends the
 * work straight back to ask again, without ever waiting. Under `writes:
 * operator` the request is the operator's, made when the turn was said, and
 * a review since then is the answer even if it came before the record moved.
 */
function askedAgainAt(record: TicketRecord): string | undefined {
  const last = record.history.at(-1);
  if (last?.from !== "RE_REVIEW" || last.to !== "HUMAN_REVIEW") return undefined;
  // Keyed as `handOver` keyed it while the record was in RE_REVIEW: one round per entry into it.
  const round = record.history.filter((moved) => moved.to === "RE_REVIEW").length;
  return record.handedOverAt?.[`request-review@${record.reviewer}@round${round}`] ?? last.at;
}

/** One review by the reviewer, on the current head, submitted after `since` — all three on the same review. */
function reviewedSince(pr: PullRequestView, reviewer: string, since: string): boolean {
  const who = reviewer.toLowerCase();
  const after = Date.parse(since);
  return pr.reviews.some((review) =>
    review.author.toLowerCase() === who && review.commitSha === pr.headSha && Date.parse(review.submittedAt) > after);
}

function planHumanFix(record: TicketRecord, obs: Observation, policy: Policy): Plan {
  const pr = requirePullRequest(obs, "HUMAN_FIX");
  if (isPlan(pr)) return pr;

  const open = outstanding(pr, "human", record);
  if (open.length > 0) {
    const tooLarge = tooLargeForAnAgent(pr, policy);
    if (tooLarge) return handBack(record, pr, policy, tooLarge, open.map((t) => t.id));

    return act(`judging ${open.length} human thread(s)`, {
      type: "address-threads",
      threadIds: open.map((t) => t.id),
      from: "human",
      ...settledDiscussion(record),
    });
  }

  const disagreed = disagreements(record);
  const alreadyEscalated = record.escalation && !record.escalation.resolvedAt;

  if (disagreed.length > 0 && !alreadyEscalated) {
    return advance("ESCALATED", `${disagreed.length} comment(s) need the owner's call`, {
      type: "escalate",
      reason: disagreed.map((d) => `${d.threadId}: ${d.note}`).join("\n"),
      threadIds: disagreed.map((d) => d.threadId),
    });
  }

  return advance("RE_REVIEW", "every comment was addressed");
}

/**
 * Back to where the escalation interrupted the work, once the owner answers.
 *
 * A record escalated before the resume point was remembered has none, and
 * goes where every escalation used to: the comments, judged again.
 */
function planEscalated(record: TicketRecord, obs: Observation, policy: Policy): Plan {
  if (obs.escalationAnswered) {
    const back = record.resumeAt ?? "HUMAN_FIX";
    return advance(back, `the owner decided, back to ${back} where the escalation stopped it`);
  }
  const escalation = record.escalation;
  const discussion = escalation && discussing(record, obs.conversation, policy, escalation.askedAt, escalation.reason);
  if (discussion) {
    const threadIds = disagreements(record).map((verdict) => verdict.threadId);
    return act(`answering ${discussion.turns.length} turn(s) of the owner's discussion; nothing is decided yet`, {
      ...discussion,
      ...(record.clarification?.length ? { clarification: record.clarification } : {}),
      ...(threadIds.length ? { threadIds } : {}),
    });
  }
  return wait(policy.pollBackoffMs, "waiting for the owner to settle a disagreement");
}

function planReReview(record: TicketRecord): Plan {
  if (!record.reviewer) {
    return advance("REVIEWER_ASSIGNED", "no reviewer is recorded for this ticket");
  }
  return advance("HUMAN_REVIEW", `asking ${record.reviewer} to look again`, {
    type: "request-rereview",
    host: record.reviewer,
  });
}

function planQaHandoff(record: TicketRecord, obs: Observation, policy: Policy): Plan {
  // Somebody already handed it over — another repository's work item, or
  // the operator — and handing it over twice is not a second handoff.
  if (handedToQa(obs)) return advance("DONE", `${obs.ticket.id} is already in QA and owned by ${obs.roster.qa.tracker}`);

  const joined = joinRepositories(obs, policy);
  if (joined) return joined;

  const firstLook = looksIn(record, "QA_HANDOFF") === 0;

  if (!isConfirmedFor(obs.roster, obs.now)) {
    return wait(
      policy.rosterBackoffMs,
      `the roster was last confirmed on ${obs.roster.confirmedOn}, not today`,
      ...(firstLook
        ? ([
            {
              type: "announce" as const,
              text: `Confirm today's QA owner before I hand over ${record.id}.`,
            },
          ] as const)
        : []),
    );
  }

  if (!obs.roster.qa.available) {
    return wait(
      policy.rosterBackoffMs,
      `${obs.roster.qa.tracker} is marked unavailable for QA`,
      ...(firstLook
        ? ([
            {
              type: "announce" as const,
              text: `The QA owner for ${record.id} is away, who takes it?`,
            },
          ] as const)
        : []),
    );
  }

  return advance("DONE", `handing ${record.id} to ${obs.roster.qa.tracker}`, {
    type: "hand-off-to-qa",
    tracker: obs.roster.qa.tracker,
  });
}

/**
 * One ticket in several repositories is one work item per repository, and QA
 * receives it once, when every one of them has merged.
 *
 * The first repository's item is the one that hands it over, so two items
 * reaching this state together cannot hand it over twice. The others wait
 * until they see it handed over rather than finishing first: which one is
 * first follows the labels, and an item that had already finished could not
 * take the handoff over when the labels were reordered under it. A
 * repository added later is read here like the rest, so the handoff waits
 * for it too.
 */
function joinRepositories(obs: Observation, policy: Policy): Plan | null {
  const repositories = obs.repositories ?? [];
  if (repositories.length < 2) return null;

  const open = repositories.filter((repository) => !repository.merged).map((repository) => repository.repo);
  if (open.length > 0) {
    return wait(policy.pollBackoffMs, `${obs.ticket.id} waits for ${open.join(", ")} to merge before QA`);
  }

  // The others finish on the status alone: the owner the first one assigned
  // is the first one's to check, and the roster may have moved since.
  const leader = repositories[0]!.repo;
  if (leader !== obs.ticket.repo) {
    return obs.inQa
      ? advance("DONE", `${leader}'s work item handed ${obs.ticket.id} to QA`)
      : wait(policy.pollBackoffMs, `every repository merged; waiting for ${leader}'s work item to hand ${obs.ticket.id} to QA`);
  }
  return null;
}

import { PullRequestView } from "@amykit/core";
import { Comment, ReplyAnswer, ReplyKind } from "@amykit/core";
import { Roster } from "./roster.js";
import { Ticket } from "./ticket.js";

/**
 * A snapshot of the outside world for one ticket, gathered before deciding.
 *
 * The decision function reads nothing else, so a test can put the machine in
 * any situation by building one of these.
 */
export interface Observation {
  ticket: Ticket;
  /** Null until a pull request exists for the ticket's branch. */
  pullRequest: PullRequestView | null;
  /**
   * Open reviews per host login, counted across every repository the team
   * uses. Counting one repository would send every review to whoever happens
   * to be quiet in that one.
   */
  reviewLoad: Readonly<Record<string, number>>;
  roster: Roster;
  /**
   * The conversation on the ticket, oldest first, in full.
   *
   * Fetched where it is used — a poll that is only waiting for a review does
   * not pay for text — and carried whole rather than reduced to a boolean, so
   * the state that re-reads the ticket can put the answer in front of the
   * agent instead of merely knowing one arrived.
   */
  conversation: Said[];
  /**
   * Whether the owner has decided an escalation: a reply that reads as a
   * decision under the policy, not merely any reply.
   */
  escalationAnswered: boolean;
  /**
   * Whether this work item's repository has left the ticket — a label taken
   * off, or a ticket that grew labels none of which is the repository its
   * work started in. Discovery no longer offers it, so the item is retired
   * rather than left to hand the ticket over beside the ones that remain.
   */
  retired?: boolean;
  /**
   * Whether the ticket already sits in the QA status, as the tracker reports
   * it. Read so a QA handoff the operator made by hand is something the
   * machine can see; absent is no.
   */
  inQa?: boolean;
  /**
   * For a ticket in more than one repository, each one and whether its pull
   * request has merged, in the tracker's order. Read only at the QA handoff,
   * which is the one state that joins them; absent everywhere else.
   */
  repositories?: readonly { repo: string; merged: boolean }[];
  now: Date;
}

/**
 * One thing said back, and what it is when the medium let the person say.
 * Unmarked is the common case, and `policy.conversation` reads it.
 */
export type Said = Comment & { kind?: ReplyKind; answer?: ReplyAnswer };

export interface Policy {
  maxImplementAttempts: number;
  maxGateAttempts: number;
  /** How long to hold in a waiting state before looking again. */
  pollBackoffMs: number;
  /** How long to hold while the roster needs confirming. */
  rosterBackoffMs: number;
  /**
   * How many open reviews one person may be carrying before this machine
   * stops adding to their pile. Review time is somebody else's, and it is
   * the one currency here that cannot be topped up.
   */
  maxOpenReviewsPerReviewer: number;
  /**
   * How large a pull request may get before this machine stops handing it to
   * an agent, in files and in changed lines.
   *
   * Asked of a number the forge already knew, before any call, because the
   * whole point of a ceiling on cost is that reaching it costs nothing. A
   * five-hundred-file review is where an agent is least likely to help and
   * most likely to be expensive about it, and the honest move there is to
   * hand it back rather than to try three times.
   *
   * Zero switches the ceiling off, for somebody who would rather it always
   * tried.
   */
  maxPullRequestFiles: number;
  maxPullRequestLines: number;
  /**
   * Who makes the tracker and code-host writes: this machine, or the
   * operator. With `operator`, every write is said once instead of made, and
   * the machine waits until it sees the effect.
   */
  writes: "machine" | "operator";
  /**
   * How a reply nobody marked reads in a waiting state. `answer` takes it as
   * the decision, which is how this machine always read one; `discuss` takes
   * it as a turn in a discussion, answered in the thread while the work
   * waits for a reply marked as the decision. A marked reply reads as marked
   * under either.
   */
  conversation: "answer" | "discuss";
}

export const DEFAULT_POLICY: Policy = {
  maxImplementAttempts: 3,
  maxGateAttempts: 3,
  pollBackoffMs: 5 * 60 * 1000,
  rosterBackoffMs: 30 * 60 * 1000,
  maxOpenReviewsPerReviewer: 2,
  maxPullRequestFiles: 60,
  maxPullRequestLines: 2000,
  writes: "machine",
  conversation: "answer",
};

import { Moved, Plan, applyPlan, movedBy } from "@amykit/core";
import {
  AttemptOutcome,
  Discussion,
  Escalation,
  ThreadVerdict,
  TicketRecord,
  TriageOutcome,
} from "./record.js";
import { TicketState } from "./state.js";

/**
 * What executing a plan's actions produced.
 *
 * The engine fills in only the fields its actions actually produced, so this
 * stays honest about what happened rather than guessing.
 */
export interface EffectOutcomes {
  triage?: TriageOutcome;
  /** The conversation a triage read, when it was reading an answer. */
  clarification?: string[];
  implementation?: AttemptOutcome;
  continuationContext?: string | null;
  waited?: { notATry: true; retryAfterMs: number };
  /** The repository and commit the implementation left the work at. */
  implemented?: { repo: string; revision?: string };
  pullRequestNumber?: number;
  reviewer?: string;
  verdicts?: ThreadVerdict[];
  escalation?: Escalation;
  /** Set when the owner has settled an escalation. */
  escalationResolvedAt?: string;
  /** The discussion that settled it, with the decision last. */
  escalationDecision?: string[];
  /** The turns a discussion answered this look, and the answer. */
  discussed?: Discussion;
  /** The keys of the writes this look handed to the operator. */
  handedOver?: string[];
  /** When this look said them. */
  handedOverAt?: string;
}

/**
 * Folds this workflow's own outcomes into a record.
 *
 * The core folds the state, the attempt count and the history; it cannot fold
 * these, because it does not know what a triage or a gate result is. Pure,
 * and the only place a ticket record changes shape, so the rules that stop
 * the machine looping live in one readable function.
 */
export function applyOutcomes(record: TicketRecord, outcomes: EffectOutcomes): TicketRecord {
  const next: TicketRecord = { ...record, judged: [...record.judged] };

  if (outcomes.triage) next.triage = outcomes.triage;
  if (outcomes.clarification?.length) next.clarification = outcomes.clarification;
  if (outcomes.implementation) next.lastImplementation = outcomes.implementation;
  applyContinuation(next, outcomes.continuationContext);
  if (outcomes.implemented) next.implemented = outcomes.implemented;
  if (outcomes.pullRequestNumber !== undefined) {
    next.pullRequestNumber = outcomes.pullRequestNumber;
  }
  if (outcomes.reviewer) next.reviewer = outcomes.reviewer;

  mergeVerdicts(next, outcomes.verdicts);

  mergeHandedOver(next, outcomes);

  if (outcomes.escalation) next.escalation = outcomes.escalation;

  mergeDiscussion(next, outcomes.discussed);

  if (outcomes.escalationResolvedAt && next.escalation) {
    next.escalation = {
      ...next.escalation,
      resolvedAt: outcomes.escalationResolvedAt,
      ...(outcomes.escalationDecision?.length ? { decision: outcomes.escalationDecision } : {}),
    };

    // The owner's answer changes the judgement, so every comment that was
    // parked as a disagreement has to be looked at again rather than staying
    // parked forever.
    next.judged = next.judged.filter((j) => j.verdict !== "disagreed");
  }

  return next;
}

function applyContinuation(
  record: TicketRecord,
  continuation: string | null | undefined,
): void {
  if (continuation === null) delete record.continuationContext;
  else if (continuation) record.continuationContext = continuation;
}

/**
 * Remembers the state an escalation interrupted, and forgets it on the way
 * back out.
 *
 * Read from the move, because the record handed to a fold has already made
 * it: its `state` is `ESCALATED` on every advance into it, and a guard written
 * against `state` excludes every escalation there is.
 *
 * Leaving `ESCALATED` also starts every retry budget again. The owner's
 * answer is new information, and a state that gave up on its attempts would
 * otherwise give up again on its very first look back.
 */
export function applyTransition(record: TicketRecord, moved: Moved | null): TicketRecord {
  if (!moved) return record;
  // A round of checks is counted where it is judged, so the ceiling on
  // rounds speaks about checks that found something, whichever lane did.
  if (moved.to === "verdict" && moved.from === "checks") {
    return { ...record, attempts: { ...record.attempts, verdict: (record.attempts.verdict ?? 0) + 1 } };
  }
  if (moved.to === "ESCALATED" && moved.from !== "ESCALATED") {
    return { ...record, resumeAt: moved.from as TicketState };
  }
  if (moved.from === "ESCALATED") {
    const { resumeAt: _resumed, ...rest } = record;
    return { ...rest, attempts: {}, looks: {} };
  }
  return record;
}

/** Adds the writes this look handed to the operator, and when it said them. */
function mergeHandedOver(record: TicketRecord, outcomes: EffectOutcomes): void {
  if (!outcomes.handedOver?.length) return;
  record.handedOver = [...new Set([...(record.handedOver ?? []), ...outcomes.handedOver])];
  const at = outcomes.handedOverAt;
  if (at) record.handedOverAt = { ...record.handedOverAt, ...Object.fromEntries(outcomes.handedOver.map((key) => [key, at])) };
}

/**
 * Adds what one look discussed to the wait it belongs to, and takes back the
 * attempt the look was counted as: a discussion is not work done in the
 * state, and must never be what spends a state's retries.
 */
function mergeDiscussion(record: TicketRecord, discussed: Discussion | undefined): void {
  if (!discussed) return;
  const before = record.discussion?.since === discussed.since ? record.discussion.lines : [];
  record.discussion = { since: discussed.since, upTo: discussed.upTo, lines: [...before, ...discussed.lines] };
  const counted = record.attempts[record.state] ?? 0;
  record.attempts = { ...record.attempts, [record.state]: Math.max(0, counted - 1) };
}

/** Replace a judgement by thread id, preserving unrelated prior verdicts. */
function mergeVerdicts(record: TicketRecord, verdicts: ThreadVerdict[] | undefined): void {
  for (const verdict of verdicts ?? []) {
    const existing = record.judged.findIndex((judged) => judged.threadId === verdict.threadId);
    if (existing === -1) record.judged.push(verdict);
    else record.judged[existing] = verdict;
  }
}

/**
 * The whole fold for one look: what the core knows how to do, then what only
 * this workflow knows how to do.
 *
 * The two touch disjoint fields, so the order is a readability choice rather
 * than a correctness one.
 */
export function applyTicketPlan(
  record: TicketRecord,
  plan: Plan,
  outcomes: EffectOutcomes,
  now: Date,
): TicketRecord {
  return applyTransition(
    applyOutcomes(applyPlan(record, plan, now, outcomes), outcomes),
    movedBy(record, plan),
  );
}

import {
  Agent,
  AskContext,
  BRANCH_SETTINGS,
  BriefStore,
  CodeHost,
  ConfigSchema,
  ConfigOf,
  Conversation,
  Gate,
  HarnessReply,
  Notifier,
  PluginCheck,
  Tracker,
  Worktree,
  call,
  defineOperation,
  defineWorkflow,
  fail,
  optional,
  port,
  scopeOf,
} from "@amykit/core";
import { z } from "zod";
import { after, before, decide } from "./machine.js";
import { DEFAULT_POLICY, Policy } from "./observation.js";
import { TicketRecord } from "./record.js";
import { EXAMPLE_ROSTER, ROSTER_FILE, Roster, confirmRoster, isConfirmedFor, loadRoster } from "./roster.js";
import { actionsFor, discover, observe, progress, remember, splitWorkId } from "./actions.js";
import { Finding, gateLane, selfReviewLane } from "./lanes.js";

type Settings = ConfigOf<typeof configSchema>;

/** One person on the roster, as the roster operations answer it. */
const member = z.object({
  host: z.string().describe("login"),
  tracker: z.string().describe("tracker"),
  available: z.enum(["in", "out"]).describe("today"),
});

const roster = {
  reviewers: z.array(member).describe("reviewers"),
  qa: member.describe("qa"),
};

/** The roster as an operation answers it: who, and whether they are in. */
function rosterOutput(read: Roster) {
  const one = (person: Roster["qa"]) => ({ host: person.host, tracker: person.tracker, available: person.available ? "in" as const : "out" as const });
  return { reviewers: read.reviewers.map(one), qa: one(read.qa) };
}

const NO_ROSTER = { "ticket-to-qa.no_roster": { description: "the profile has no roster file, or one missing confirmedOn, reviewers or qa" } };

/** The roster file, or the declared error naming why it cannot be read. */
function readRoster(state: string, home: string): Roster | ReturnType<typeof fail> {
  try {
    return loadRoster(state, home);
  } catch (error) {
    return fail("ticket-to-qa.no_roster", error instanceof Error ? error.message : String(error));
  }
}

/**
 * Who is reviewing, as this workflow's own operations: `amy roster` and
 * `amy roster confirm`.
 *
 * It used to be the host's, on every install, for the one workflow that
 * assigns anybody. Here it is a file beside the profile's records: two teams
 * running two ticket-to-qa profiles do not share reviewers, and a machine
 * that never assigns one has no roster to keep.
 */
const showRoster = defineOperation({
  id: "ticket-to-qa.show-roster",
  domain: "ticket-to-qa",
  summary: "Print the roster and whether it is current",
  description: "Reads this profile's roster file and says who is in and whether it was confirmed today. Changes nothing.",
  input: z.object({}),
  output: z.object({
    confirmedOn: z.string().describe("confirmed on"),
    current: z.enum(["current", "stale"]).describe("today"),
    ...roster,
  }),
  errors: NO_ROSTER,
  writes: [],
  http: { method: "get", path: "/ticket-to-qa/roster" },
  cli: { words: ["roster", "show"], default: true },
  examples: [{
    summary: "a roster confirmed today",
    input: {},
    output: {
      confirmedOn: "2026-11-07",
      current: "current",
      reviewers: [{ host: "ada", tracker: "ada@example.test", available: "in" }],
      qa: { host: "grace", tracker: "grace@example.test", available: "in" },
    },
  }],
  async handler(_input, context) {
    const { state, home } = scopeOf<Settings>(context, "ticket-to-qa.show-roster");
    const read = readRoster(state, home);
    if ("error" in read) return read;
    return { confirmedOn: read.confirmedOn, current: isConfirmedFor(read, new Date()) ? "current" as const : "stale" as const, ...rosterOutput(read) };
  },
});

const confirmRosterOperation = defineOperation({
  id: "ticket-to-qa.confirm-roster",
  domain: "ticket-to-qa",
  summary: "Stamp the roster with today's date",
  description: "Writes today's date into this profile's roster file, so the machine assigns from it again today. Changes nobody on it.",
  input: z.object({}),
  output: z.object({
    confirmedOn: z.string().describe("confirmed for"),
    ...roster,
  }),
  errors: NO_ROSTER,
  writes: ["roster"],
  http: { method: "post", path: "/ticket-to-qa/roster/confirmation" },
  cli: { words: ["roster", "confirm"] },
  examples: [{
    summary: "confirming today's roster",
    input: {},
    output: {
      confirmedOn: "2026-11-07",
      reviewers: [{ host: "ada", tracker: "ada@example.test", available: "in" }],
      qa: { host: "grace", tracker: "grace@example.test", available: "in" },
    },
  }],
  async handler(_input, context) {
    const { state, home } = scopeOf<Settings>(context, "ticket-to-qa.confirm-roster");
    // Only a roster that cannot be read is the declared error; a write that
    // fails after it was read — a full disk, a read-only directory — is not,
    // and propagates as internal.
    const read = readRoster(state, home);
    if ("error" in read) return read;
    const confirmed = confirmRoster(state, new Date(), home);
    return { confirmedOn: confirmed.confirmedOn, ...rosterOutput(confirmed) };
  },
});

/** A roster nobody confirmed today is a review nobody would answer. */
const rosterCheck: PluginCheck<Settings> = {
  name: "roster confirmed for today",
  run({ state, home }) {
    const roster: Roster = loadRoster(state, home);
    const current = isConfirmedFor(roster, new Date());
    return {
      label: "roster confirmed for today",
      ok: current,
      detail: current ? "" : `last confirmed ${roster.confirmedOn}, run \`amy roster confirm\``,
    };
  },
};

export const configSchema = {
  repos: { type: "string[]", required: true, description: "every repository review load is counted across" },
  ...BRANCH_SETTINGS,
  qaStatusName: {
    type: "string",
    required: true,
    example: "In QA",
    description: "the status a ticket moves to when it is handed to QA",
  },
  reviewerHints: {
    type: "record",
    description: "guidance appended to the review prompt when answering a particular reviewer, by host login",
    default: {},
  },
  "policy.maxImplementAttempts": {
    type: "number",
    default: 3,
    description: "how many times an agent may try to implement one ticket before it is escalated",
  },
  "policy.maxGateAttempts": {
    type: "number",
    default: 3,
    description: "how many times the gate may see one change before the work is escalated",
  },
  "policy.pollBackoffMs": {
    type: "number",
    default: 5 * 60 * 1000,
    description: "how long a waiting state holds before it looks again: waiting on an answer, or on a review",
  },
  "policy.rosterBackoffMs": {
    type: "number",
    default: 30 * 60 * 1000,
    description: "how long to hold while the roster is waiting to be confirmed",
  },
  "policy.maxOpenReviewsPerReviewer": {
    type: "number",
    default: 2,
    description:
      "how many open reviews one person may be carrying before this machine stops adding to their pile. Review time is somebody else's, and it is the one currency here that cannot be topped up",
  },
  "policy.maxPullRequestFiles": {
    type: "number",
    default: 60,
    description:
      "how large a pull request may get, in files, before this machine stops handing it to an agent. The forge has already told us the size, so a pull request nobody should automate is handed back before an agent is called. Zero switches it off",
  },
  "policy.maxPullRequestLines": {
    type: "number",
    default: 2000,
    description: "how large a pull request may get, in changed lines, under the same rule as maxPullRequestFiles. Zero switches it off",
  },
  "policy.writes": {
    type: "string",
    default: "machine",
    description:
      "machine: amy comments, opens pull requests, requests reviews and moves the ticket to QA. operator: each of those is said to you once instead, and amy waits until it sees you made it. Nothing is written on the tracker or the code host",
  },
  "policy.conversation": {
    type: "string",
    default: "answer",
    description:
      "answer: a reply in the work's thread is your decision, and the work moves on it. discuss: a reply is a turn in a discussion, answered in the thread while the work waits; mark the reply that decides and only that one moves it. A reply you marked reads as marked under either, and without a thread a comment on the ticket is always the decision",
  },
  budget: {
    type: "record",
    description: "agent budget, including an optional progress block that stops repeated no-evidence runs",
    default: {},
  },
} satisfies ConfigSchema;

export const needs = {
  tracker: port<Tracker>(),
  conversation: optional<Conversation>(),
  "code-host": port<CodeHost>(),
  agent: port<Agent & { ask(prompt: string, cwd: string, context?: AskContext): Promise<HarnessReply> }>(),
  gate: port<Gate>(),
  notifier: port<Notifier>(),
  brief: optional<BriefStore>(),
  worktree: optional<Worktree>(),
};

export const plugin = defineWorkflow({
  name: "ticket-to-qa",
  pluginName: "@amykit/workflow-ticket-to-qa",
  configSchema,
  policy: DEFAULT_POLICY,
  needs,
  // A project is brief, work and proof; a ticket's walk is the work half
  // alone. The ticket already carries its own statement of the work, and the
  // gate's scenario run before every pull request is what proves a ticket's
  // code holds — so no brief phase and no proving phase of amy's own.
  phases: {
    brief: "the ticket itself says what the work is; grooming a feature is not what this walk does, so no brief phase runs first",
    prove: "the command gate's scenario run after every implementation is what proves the work; this walk keeps no separate proving phase",
  },
  trackerWrites: ({ policy }) => writesOf(policy) === "operator"
    ? []
    : ["comment", "set-status", "assign", "create-follow-up"],
  codeHostWrites: ({ policy }) => writesOf(policy) === "operator"
    ? []
    : ["open-pull-request", "request-review", "resolve-thread"],
  runtimePolicy: ({ ports, policy }) => ({
    ...policy,
    writes: writesOf(policy),
    conversation: conversationOf(policy, ports.conversation),
  }),
  // The gate and the self-review, as two lanes of the `checks` fork: each
  // lent the implementation's commit, read-only, and each folded back into
  // the record the implementation is retried from.
  calls: {
    GATE: call(gateLane, {
      input: (work: TicketRecord) => checkInput(work),
      revision: (work: TicketRecord) => work.implemented?.revision,
      output: {
        GREEN: (work: TicketRecord, found: Finding) => ({ ...work, lastGate: found }),
        RED: (work: TicketRecord, found: Finding) => ({ ...work, lastGate: found }),
      },
    }),
    SELF_REVIEW: call(selfReviewLane, {
      input: (work: TicketRecord) => ({ ...checkInput(work), ticketId: splitWorkId(work.id).ticketId }),
      revision: (work: TicketRecord) => work.implemented?.revision,
      output: {
        APPROVED: (work: TicketRecord, found: Finding) => ({ ...work, lastSelfReview: { ...found, verdict: "APPROVED" as const } }),
        CHANGES_ASKED: (work: TicketRecord, found: Finding) => ({ ...work, lastSelfReview: { ...found, verdict: "CHANGES_ASKED" as const } }),
      },
    }),
  },
  before,
  decide,
  after,
  operations: [showRoster, confirmRosterOperation],
  checks: [rosterCheck],
  files: [{ path: ROSTER_FILE, content: EXAMPLE_ROSTER }],
  record: () => ({ judged: [] }),
  progress,
  discover,
  observe,
  actions: (scope) => actionsFor(scope.policy),
  remember,
});


/** Where the work is and the commit to check, as both checks are called with it. */
function checkInput(work: TicketRecord): { repo: string; workId: string; revision?: string } {
  const repo = work.implemented?.repo;
  if (!repo) throw new Error(`${work.id} reached the checks with no repository recorded for its implementation`);
  return { repo, workId: work.id, ...(work.implemented?.revision ? { revision: work.implemented.revision } : {}) };
}

function writesOf(policy: Policy): Policy["writes"] {
  if (policy.writes !== "machine" && policy.writes !== "operator") {
    throw new Error(`ticket-to-qa policy.writes must be "machine" or "operator", not ${JSON.stringify(policy.writes)}`);
  }
  return policy.writes;
}

function conversationOf(policy: Policy, conversation: Conversation | undefined): Policy["conversation"] {
  if (policy.conversation !== "answer" && policy.conversation !== "discuss") {
    throw new Error(`ticket-to-qa policy.conversation must be "answer" or "discuss", not ${JSON.stringify(policy.conversation)}`);
  }
  return conversation ? policy.conversation : "answer";
}

import { AttemptOutcome, WorkRecord } from "@amykit/core";
import { ThreadVerdict, TriageOutcome } from "./agent-steps.js";
import { TicketState } from "./state.js";

// Re-exported so the record's fields mean the same thing to every consumer:
// the attempt from the core, the triage and verdicts from this workflow.
export type { AttemptOutcome, ThreadVerdict, TriageOutcome };

export interface Escalation {
  reason: string;
  askedAt: string;
  followUpTicketId?: string;
  resolvedAt?: string;
  /**
   * The discussion that settled it, attributed, with the decision last — what
   * the step it resumes is prompted with, so the agent acts on what was
   * concluded rather than on the first thing said.
   */
  decision?: string[];
}

/**
 * What has been discussed during one wait, and answered.
 *
 * Keyed by the instant the wait began — the question asked, the escalation
 * raised — so a new wait starts a new discussion rather than inheriting one.
 */
export interface Discussion {
  since: string;
  /** The newest turn answered; a turn at or before it is not asked again. */
  upTo: string;
  /** Each turn and each answer, attributed, oldest first. */
  lines: string[];
}

/**
 * Everything the machine remembers about one ticket, persisted between looks.
 *
 * Outcomes live here rather than being returned from the decision function,
 * because the work that produces them takes far longer than one look and has
 * to survive a crash.
 */
export interface TicketRecord extends WorkRecord {
  /** Narrowed from the core's plain label to this workflow's own states. */
  state: TicketState;
  triage?: TriageOutcome;
  /**
   * What the questions before the work were answered with, and what was
   * discussed on the way — the conversation the triage read when it cleared,
   * kept so the implementation is told it too.
   */
  clarification?: string[];
  lastImplementation?: AttemptOutcome;
  /** Kept separately so a limit cannot masquerade as failed-attempt evidence. */
  continuationContext?: string;
  /**
   * Where the last implementation left the work: its repository and the
   * commit, which both checks are lent read-only rather than the base. A
   * record an older version implemented holds only the repository, filled in
   * on its way to the checks, and is checked in the work's own tree.
   */
  implemented?: { repo: string; revision?: string };
  /** What the gate lane said about the last commit it checked. */
  lastGate?: AttemptOutcome;
  /**
   * What the work's own review of itself last said, against the brief, and
   * whether it asked for changes: the self-review lane's half of the verdict.
   */
  lastSelfReview?: AttemptOutcome & { verdict?: "APPROVED" | "CHANGES_ASKED" };
  pullRequestNumber?: number;
  reviewer?: string;
  /** Threads already judged, so the same comment is never worked twice. */
  judged: ThreadVerdict[];
  escalation?: Escalation;
  /** The discussion in the current wait, when anybody started one. */
  discussion?: Discussion;
  /**
   * The state an escalation interrupted, so the owner's answer sends the work
   * back there rather than to wherever the machine happens to resume.
   *
   * Folded from the transition, never from `state`: by the time the fold
   * runs, `state` is already `ESCALATED` on every move into it.
   */
  resumeAt?: TicketState;
  /**
   * The writes already handed to the operator, by key, so each one is said
   * once and the looks after it wait for its effect instead of saying it
   * again.
   */
  handedOver?: string[];
  /**
   * When each of those was said, by key. A review the operator was asked to
   * request counts only if it was requested, or submitted, after this: a
   * review already on the head from the round before is not an answer.
   */
  handedOverAt?: Record<string, string>;
}

export function judgedThreadIds(record: TicketRecord): string[] {
  return record.judged.map((j) => j.threadId);
}

export function disagreements(record: TicketRecord): ThreadVerdict[] {
  return record.judged.filter((j) => j.verdict === "disagreed");
}

import { PullRequestView, ReviewThread } from "@amykit/core";

/**
 * The automated reviewer answers to three different names depending on which
 * API you ask: `copilot-pull-request-reviewer[bot]` on REST reviews,
 * `Copilot` on REST review comments, and `copilot-pull-request-reviewer` on
 * GraphQL. Adapters normalise to one of these, and this is the only place
 * that decides what counts.
 */
const AUTOMATED_REVIEWER_LOGINS = [
  "copilot-pull-request-reviewer[bot]",
  "copilot-pull-request-reviewer",
  "copilot",
];

export function isAutomatedReviewer(author: string): boolean {
  return AUTOMATED_REVIEWER_LOGINS.includes(author.toLowerCase());
}

/** Threads that still need an answer, from either the bot or a human. */
export function unresolvedThreads(
  pr: PullRequestView,
  from: "automated" | "human",
): readonly ReviewThread[] {
  return pr.threads.filter((t) => {
    if (t.isResolved) return false;
    const automated = isAutomatedReviewer(t.author);
    return from === "automated" ? automated : !automated;
  });
}

/**
 * Whether the given author has reviewed the current head.
 *
 * This has to be asked per head rather than "has reviewed at all", because
 * the automated reviewer posts a COMMENTED review even when it has nothing
 * to say. Treating any review as a signal would let a push go out
 * unreviewed, and treating "no threads" as approval would skip the wait
 * entirely.
 */
export function hasReviewedHead(pr: PullRequestView, author: string): boolean {
  return pr.reviews.some(
    (r) => r.author.toLowerCase() === author.toLowerCase() && r.commitSha === pr.headSha,
  );
}

export function automatedReviewerSawHead(pr: PullRequestView): boolean {
  return pr.reviews.some((r) => isAutomatedReviewer(r.author) && r.commitSha === pr.headSha);
}

import fs from "node:fs";
import path from "node:path";
import YAML from "yaml";

export interface RosterMember {
  /** How the tracker identifies them, normally an email. */
  tracker: string;
  /** How the code host identifies them, a login. */
  host: string;
  /** Cleared when someone is on leave. */
  available: boolean;
}

export interface Roster {
  /**
   * The date the roster was last confirmed, as `YYYY-MM-DD`.
   *
   * The machine refuses to assign anybody on a workday when this is not
   * today. People go on leave without updating a config file, and assigning
   * a reviewer who is away stalls a pull request for days without anything
   * looking broken.
   */
  confirmedOn: string;
  reviewers: RosterMember[];
  qa: RosterMember;
}

/** Monday through Friday. Saturday is 6 and Sunday is 0. */
export function isWorkday(date: Date): boolean {
  const day = date.getUTCDay();
  return day >= 1 && day <= 5;
}

/** The roster this workflow keeps, at the root of the profile that mounts it. */
export const ROSTER_FILE = "roster.yaml";

export function rosterPath(state: string): string {
  return path.join(state, ROSTER_FILE);
}

/**
 * Who is reviewing today, read off this profile's own file.
 *
 * A file rather than a setting: it changes daily and confirming it is one
 * command, and two ticket-to-qa profiles belong to two teams who do not share
 * reviewers.
 *
 * `root` is the machine's own state directory, handed over by every caller
 * that holds it: an older install kept this file there, and a phase's state
 * directory sits deep enough that its parent is not the machine — left to
 * guess, the recovery below would look beside the phase and never see the
 * file the machine retired the roster into.
 */
export function loadRoster(state: string, root?: string): Roster {
  const file = rosterPath(state);
  if (!fs.existsSync(file)) {
    // An older install kept the team at the machine root until the move into
    // profiles renamed it, so one of those two names is the instruction when
    // this profile has none of its own: point at what is there rather than
    // leaving the person with a path and no way back.
    const machineRoot = root ?? path.dirname(state);
    const retired = path.join(machineRoot, "roster.yaml.moved");
    const kept = path.join(machineRoot, "roster.yaml");
    const where = fs.existsSync(retired) ? retired : fs.existsSync(kept) ? kept : undefined;
    if (where) {
      throw new Error(`no roster at ${file}; the machine's old roster is ${where} — copy it here and run \`amy roster confirm\``);
    }
    throw new Error(`no roster at ${file}; write one with amy init, or run \`amy roster confirm\` once it is there`);
  }

  const parsed = YAML.parse(fs.readFileSync(file, "utf-8")) as Partial<Roster> | null;

  if (!parsed?.confirmedOn || !parsed.reviewers?.length || !parsed.qa) {
    throw new Error(`${file} needs confirmedOn, reviewers and qa`);
  }

  return parsed as Roster;
}

/**
 * Stamps the roster with today's date.
 *
 * Deliberately a separate action from editing it, so confirming that nothing
 * changed is one command rather than a file edit somebody skips.
 */
export function confirmRoster(state: string, today: Date, root?: string): Roster {
  const roster = loadRoster(state, root);
  const confirmed: Roster = { ...roster, confirmedOn: today.toISOString().slice(0, 10) };
  fs.writeFileSync(rosterPath(state), YAML.stringify(confirmed), "utf-8");
  return confirmed;
}

/** What a profile that mounts this workflow is given, once, by `amy init`. */
